/* 2020年11月30日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"r02-20201130-9","dateIso":"2020-11-30","title":"2020年11月30日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5018#one","fetchedAt":"2026-08-14","characters":81740,"voices":[{"i":1,"speaker":"こんの委員長","text":"○午前１０時００分開会\nそれでは、ただいまより文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査、報告事項およびその他を予定しております。\nなお、本日は午後１時から、中途議決のための本会議が開催される予定でございますので、１１時までをめどに、一旦休憩を入れさせていただく予定です。各委員におかれましては、そのことをご考慮いただき、簡潔な質疑にご協力をよろしくお願いいたします。\nまた、本日は、審査の都合上、お手元に配付してございます審査・調査予定表の順番を一部入れ替えて進めてまいります。\nなお、本日の委員会もこれまで同様に、新型コロナウイルス感染症拡大防止のため、委員会室のレイアウトを変更するとともに、理事者の出席も必要最小限とし、適宜入替えを行いながら進めてまいります。\n本日も、特に、会議時間が長時間にならないよう簡潔かつ効率的なご質疑にご協力のほど、よろしくお願いいたします。\n────────────────────────────────────────────\n１ 議案審査\n(4) 第９７号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例について\n(5) 第９８号議案 学校教育職員の給与に関する条例の一部を改正する条例について"},{"i":2,"speaker":"こんの委員長","text":"それでは、予定表の１の議案審査を行います。\n予定表では(1)第６６号議案の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、初めに、(4)第９７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例について、および(5)第９８号議案、学校教育職員の給与に関する条例の一部を改正する条例についてを一括議題に供します。\n本件２議案につきましては、関連する内容のため一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\nそれでは本件につきまして、理事者より一括してご説明願います。"},{"i":3,"speaker":"工藤指導課長","text":"それでは私から、第９７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例について、第９８号議案、学校教育職員の給与に関する条例の一部を改正する条例について、併せて説明させていただきます。資料につきましては、資料１枚目、１ページおよび２ページで説明させていただきます。\n両案につきましては、令和２年１０月２３日に行われました特別区人事委員会勧告を踏まえ、幼稚園教育職員および学校教育職員、いわゆる区固有教員の給与に関し、所要の改正を行うものでございます。\n資料１ページ目の１、特別給（期末手当）の年間支給月数の改正についてご説明申し上げます。こちらは特別区人事委員会の勧告に基づき、勧告どおり特別給の年間支給月数を、現行の４.６５月から４.６月に０.０５月引き下げ、その引下げ分を期末手当から差し引くというものでございます。\n続いて、資料をおめくりいただきまして、２ページをご覧いただければと存じます。０.０５月引下げの対応でございますが、今年度につきましては、３回ある期末手当の支給月のうち、令和２年１２月期の期末手当の支給月数を０.０５月引き下げる改正を行うものでございます。令和３年度以降につきましては、６月期および１２月期に、引下げ分の０.０５月を０.０２５月ずつ均等に割り振る改正を行うものでございます。\n次に２ページ目、２、施行期日でございますが、１２月期の期末手当の支給月数に係る改正につきましては、公布の日から施行することとし、令和３年度以降の期末手当支給月数に係る改正につきましては、令和３年４月１日より施行することとするものでございます。"},{"i":4,"speaker":"こんの委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":5,"speaker":"安藤委員","text":"そもそものところで申し訳ないのですけれども、区立幼稚園教諭のほうの給与水準の体系の基本的な考え方というのは何なのか、改めて伺いたいというのが１点です。\nそれと、管理職員というのは、具体的にはどの役職以上を指すのかというのをお伺いします。\nそれと、前回の１１月９日の委員会で報告がありましたけれども、それ以後の労使交渉の結果について、妥結したのでしょうか、伺いたいと思います。"},{"i":6,"speaker":"工藤指導課長","text":"それでは、３点ご質問をいただきました。\n幼稚園教育職員の給与につきましては、区職員と同じというところで伺っているところでございます。\n管理職につきましては、園長、副園長が管理職として勤務しているものでございます。\nまた、交渉のところにつきましては、１１月１９日に妥結したと情報をいただいているところでございます。"},{"i":7,"speaker":"安藤委員","text":"今回の引下げという改定なのですけれども、これは何年ぶりになるのかというのと、前回、勧告の概要を報告いただきましたが、そのときに、今回は特別給ということなのですけれども、８月１７日から９月３０日までに行った月例給の民間企業調査について、行われたということもありましたが、そちらのほうはどのような結果になったのでしょうか。改めて伺いたいと思います。"},{"i":8,"speaker":"工藤指導課長","text":"すみません、引下げ改定が何年ぶりかというのが手元に資料がないところなので、回答が難しいところでございます。\nまた、月例給につきましては、まだ必要な報告・勧告が出されていないという現状でございます。"},{"i":9,"speaker":"安藤委員","text":"月例給についても、また新たな勧告が出て下げるという方向になってしまうのかなと、今聞いて思いました。\nあと、引下げ自体は、過去の議事録を少し見てみますと、こういった形で、ここのところ引上げが続いていたので、かなり久しぶりなのではないかと思っています。\n最後にお伺いしたいのですけれども、教員の給料ということでいうと、２００５年から２０１５年までの１０年間でいいますと、教員給与というのがＯＥＣＤの平均では上がっていたのですが、日本だけが一番低い下げ幅で、７％も低下しているという状況です。あと、労働環境の悪化も相まって、小学校の教員採用倍率というのが２０００年では１２.５倍だったそうなのですけれども、２０２０年には２.８倍に下がって、下がり続けているという状況もあります。\n地方公務員法ですとか、人事委員会の勧告のルールというのがあると思うのですが、教員の賃金の低下というのは、こういう倍率が下がっていくということにも一つ表れているのかなと思うのですけれども、教育の質の低下にどうしてもつながってくる問題だと思うのですが、区教委のお考えはいかがでしょうか、伺います。"},{"i":10,"speaker":"工藤指導課長","text":"まず、給与等、またこういった制度に関しましては、制度にのっとって進めるというものと考えているところでございます。\nまた、近年の受験倍率等の低下というところは、委員ご指摘いただいておりますが、質の低下を招くということも、一方では言われているところでございます。ただ、その選考の中で採用等に至った者につきましては、教員としての資質・能力が認められるというものでございますから、もちろん育成も含めながら、しっかりと進めることが必要であると認識しているところでございます。"},{"i":11,"speaker":"あべ委員","text":"この引下げで、実際に平均でどのくらい下がるのかという試算はされていますでしょうか。幼稚園のほうと学校のほうと、両方を教えてください。"},{"i":12,"speaker":"工藤指導課長","text":"これにつきましては、どちらも職員の平均年間給与としては、約２万円の減になるというところでございます。"},{"i":13,"speaker":"こんの委員長","text":"ほかにございますでしょうか。よろしいですか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれでは、採決に入ります前に、まず第９７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、自民党からお願いします。"},{"i":14,"speaker":"芹澤副委員長","text":"自民党は賛成します。"},{"i":15,"speaker":"せお委員","text":"賛成です。"},{"i":16,"speaker":"たけうち委員","text":"賛成です。"},{"i":17,"speaker":"安藤委員","text":"賛成ですけれども、ちょっと意見を言わせていただきますが、公民較差の解消という名の下に、低いほうに結局今回は合わせるということになるのですけれども、先ほど言いましたように、子どもの健全な育ちに直接関わる教職員の、やりがいを持って働ける環境づくりには逆行するのかなという点と、消費の低迷が民間企業の賃金引下げということで、負のスパイラルにもなっていたりするような状況なので、好ましいとは言えないと思うのですけれども、こういうコロナの状況もあります。あと、労使で妥結しているということですので、それはもちろん尊重する立場なので、あえて反対はいたしません。賛成です。"},{"i":18,"speaker":"筒井委員","text":"賛成です。"},{"i":19,"speaker":"あべ委員","text":"賛成です。"},{"i":20,"speaker":"横山委員","text":"賛成します。"},{"i":21,"speaker":"こんの委員長","text":"それでは、これより、第９７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「なし」と呼ぶ者あり〕"},{"i":22,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n次に、第９８号議案、学校教育職員の給与に関する条例の一部を改正する条例につきまして、各会派の態度を確認します。\nそれでは、自民党からお願いします。"},{"i":23,"speaker":"芹澤副委員長","text":"賛成します。"},{"i":24,"speaker":"せお委員","text":"賛成です。"},{"i":25,"speaker":"たけうち委員","text":"賛成です。"},{"i":26,"speaker":"安藤委員","text":"賛成で、意見は先ほどと同じです。"},{"i":27,"speaker":"筒井委員","text":"賛成です。"},{"i":28,"speaker":"あべ委員","text":"賛成です。"},{"i":29,"speaker":"横山委員","text":"賛成です。"},{"i":30,"speaker":"こんの委員長","text":"それでは、これより、第９８号議案、学校教育職員の給与に関する条例の一部を改正する条例についてについて、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「なし」と呼ぶ者あり〕"},{"i":31,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\nなお、第９７号議案および第９８号議案の議案審査の委員長報告については、正副委員長にご一任いただきたいと思いますが、よろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":32,"speaker":"こんの委員長","text":"ありがとうございます。それでは、正副でまとめさせていただきます。\n────────────────────────────────────────────\n３ 報告事項\n(1) 専決処分の報告について（報告第２３号）"},{"i":33,"speaker":"こんの委員長","text":"それでは、議案審査は一旦これまでとさせていただきまして、次に、会議の運営上、予定表の順番を入れ替えまして、予定表の３の報告事項を聴取いたします。\n(1)専決処分の報告について（報告第２３号）を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":34,"speaker":"有馬庶務課長","text":"それでは、報告第２３号、損害賠償額の決定に関する専決処分につきまして、地方自治法の第１８０条第２項の規定に基づき、報告をさせていただきます。\n資料を併せてご覧いただきたいと思いますが、本件につきましては、鈴ケ森中学校の近隣駐車場で起きた屋根の破損事故でございます。\n鈴ケ森中学校の校庭で、硬式テニス部の活動中に生徒が打ったボールが、複数回にわたり防球ネットを飛び越えまして、隣接する駐車場の屋根、基本的には波板でございますが、それに当たり、その一部を破損したというものでございます。\n資料の裏面のところに破損状況の写真がつけてありますが、ＡからＤの５か所に穴が開いたということでございます。\nこのたび、この所有者が屋根を全面改修するということでございまして、裏面の下に書いてあるとおり、面積割合に基づいて、損害賠償額５万円を支払うというものでございます。相手方につきましては、報告に記載のとおりでございます。"},{"i":35,"speaker":"こんの委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":36,"speaker":"たけうち委員","text":"一応、確認なのですけれども、約２年間の間ぐらいで、今までは、その都度被害がここにありましたということは、１回も相手の持ち主の方から学校のほうになくて、取り替えるとなったときに、そういえばということで、まとめて請求が来たという認識でいいのかということと、もし仮にそうだとすると、今までは対応ができなかったのかもしれないけれども、今後新しいものに替えたときには、こういうタイプではなくて、仮に当たっても大丈夫な屋根になるのかもしれませんが、複数回ボールが飛び越えていくということなので、ネット関係を調整するとか、クラブ活動で何か工夫をしていくとかということは、対応はされているのか、もし分かれば教えてください。"},{"i":37,"speaker":"有馬庶務課長","text":"まず、今回これに至った経緯でございますけれども、ここの持ち主は、ここには住んでいらっしゃらない、駐車場として貸しているだけということがございまして、ここを管理している不動産会社を通じて申し出があったということです。学校はその都度、気がつかなかったのかというところが、もう一つになりますけれども、道路から見るとシャッターがしてあり、その奥の屋根ということなので、破損していたかどうかは具体的には分からなかったということがありました。\nこのたび、それを管理している不動産屋が、持ち主のほうにお話をされ、今回の結果になったというのが、今のところの経過でございます。\nこれを受けまして、今回の補修につきましては、ポリカーボネートの、今までの波板よりも少し厚いものでやるということですので、ボールが飛んだからといってすぐに壊れないようなものにするということと、それから、防球ネットの高さは１０ｍ近くあるのですが、それを即座に替えることはできないので、練習する場所、特に７年生が練習で最初に外に出してしまうということがあるので、それは逆に言うと、もう少し校庭の中のほうで対応していこうということで、活動のやり方というか、練習のやり方も見直して、対応しているところでございます。"},{"i":38,"speaker":"たけうち委員","text":"分かりました。大丈夫だと思いますけれども、通行人だとか人に、テニスの硬球だから、それほどとは思うけれども、ご高齢の方とか小さい子どもに行った場合には、物とは違う部分での損失になりますので、そういうのは一応、大変だと思いますけれども、注意していただきたいと要望して、終わります。"},{"i":39,"speaker":"あべ委員","text":"細かいお話なのですけれども、飛び出したものというのは、この駐車場の上にしか行っていないのでしょうか。近隣も一応、調べられたのでしょうか。ほかのところからは一切お話もなく、被害もなくて、この屋根だけに硬球が集中したということでしょうか。何かお分かりですか。"},{"i":40,"speaker":"有馬庶務課長","text":"ボールが飛び出したときは、一日の練習が終わったら回収に行くとか、通行人が時々気がついて拾ってくれたりとかということはあったようでございますけれども、敷地の中ということであれば、ほかは隣のマンションだったりすると、屋根が高かったりするので、そういった報告は受けておりません。基本的にここは、先ほども申し上げましたように、シャッターが下りていた奥の駐車場ということで、そこが入って探しにくかったというところがあったということでございます。"},{"i":41,"speaker":"あべ委員","text":"練習場所を変えられたということで、いいと思うのですけれども、その状態が分からないので、そこからまた新たにどこかに出てしまって、何か別のところに被害が行くということはないように、慎重に対応をお願いします。"},{"i":42,"speaker":"筒井委員","text":"防球ネットはすぐに取り替えられないので、練習場所を変えるなどの対策をされるということなのですけれども、気になるのは、平成３０年４月から令和２年５月までの間という、この期間だけ起きたという認定ですけれども、これはあまり考えたくないことなのですが、ふだんの練習中、自然と練習していてこうなったのか、それとも故意に飛ばすような生徒がいたのか、その辺りの解明というか、事実確認というのは、どうされているのでしょうか。"},{"i":43,"speaker":"有馬庶務課長","text":"この期間というのは、今の学校にいる顧問が、ボールが飛び出たことがあるというのを確認できた期間ということで、この期間ということになっております。\n部活ですので、顧問なり上級生なりがいて練習いたしますので、あえて故意に出すということは、学校からの報告は聞いておりませんので、たまたま新入生が慣れないときに、ラケットとボールがうまく当たらないで、フレームに当たって出てしまうといったことがあると報告を受けたところでございます。"},{"i":44,"speaker":"筒井委員","text":"分かりました。ただ、練習場所を変えても、またなお飛び越えるようなことなどもあり得るかもしれないので、いろいろな対応はあると思うのですけれども、今後は近隣の人とかにも直撃すると、もっと大変なことになってしまうので、再発防止をしっかりと行っていただくよう、よろしくお願いします。これは要望で終わります。"},{"i":45,"speaker":"こんの委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 専決処分の報告について（報告第２４号）"},{"i":46,"speaker":"こんの委員長","text":"次に、(2)専決処分の報告について（報告第２４号）を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":47,"speaker":"横山品川図書館長","text":"それでは、私からは、報告第２４号、損害賠償額の決定に関する専決処分の報告についてご説明申し上げます。\nこちらの専決処分でございますが、地方自治法第１８０条第１項の規定による議会の指定議決に基づき、機械式立体駐車場で起きた車載台の破損事故に伴う損害賠償額の決定につきまして、令和２年１０月７日に専決処分を行いましたので、同条第２項の規定に基づき報告させていただきます。\n事故の概要でございますが、令和２年６月２６日に品川図書館職員が、六行会総合ビルの機械式立体駐車場で庁有車を駐車する際、誤ってトランクを開けたまま駐車装置を操作したため、駐車場の車載台に車を接触させ、破損させたものです。今回の事故により、区側の責任割合は１００％で、相手方に損害金を支払うこととなりました。賠償金の額は、修理費等で５０万１,４８０円となり、区契約保険会社から相手方に支払いを行っております。\n今後、このような事故が起こらないよう、品川図書館では車両運転に関して注意を促し、安全管理を徹底してまいります。誠に申し訳ございませんでした。"},{"i":48,"speaker":"こんの委員長","text":"報告が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":49,"speaker":"安藤委員","text":"庁有車のほうの被害額というのは、どれくらいなのでしょうか。"},{"i":50,"speaker":"横山品川図書館長","text":"廃車という形になりましたので、１２８万５,２００円でございます。"},{"i":51,"speaker":"あべ委員","text":"職員の方が車を運転するのは、よくあると。これはいわゆる運転手の方なのか、それとも一般の事務職などの職員なのか。"},{"i":52,"speaker":"横山品川図書館長","text":"事務職員が運転しておりました。"},{"i":53,"speaker":"あべ委員","text":"車を運転するのも職員の方のお仕事だと思うのですけれども、その辺の安全管理ですとか、あるいは、逆に最近、車の運転免許をあまり持っていないとか、日頃運転されない方も増えてきているのかなと思うのですけれども、その辺は何か役所としては、運転技術や経験みたいなものというのは勘案しつつ、庁有車というのは運転することになっているのですか。"},{"i":54,"speaker":"横山品川図書館長","text":"委員ご指摘のとおり、職員に運転をお願いしている関係上、特別に訓練された者でないという形がありますので、運転者講習会等、研修の機会は必ず受講するように、各職場で指導しております。また、職員採用の際にも運転免許の申告と、実際に免許を持っているだけではなくて、運転できるかどうかの確認をしながら、配置をさせていただいておりますが、事実上は不足というか、なかなかきつい状況で、図書館でも実質上、１人しか運転できる人はいないという形です。"},{"i":55,"speaker":"あべ委員","text":"特別この事故というわけではないのですけれども、運転ができる人が減っている中で、運転する人だけに運転業務が集中するようになってしまって、その方に事故リスクや違反リスクも集中していくというのは、何かちょっと引っかかる。今後その辺の公平性というか、考えていらっしゃることはありますでしょうか。これは役所全体の話だと思うのですけれども。"},{"i":56,"speaker":"横山品川図書館長","text":"図書館におきましては、本の配送等を頻繁に行うので、そこの部分については専門の業者にお願いしているところですが、やはり各所の連絡事項で車を運転する機会も多いです。なので、図書館としては、運転できる人を必ず異動の際にお願いするという形を取っています。ですが、区全体ですと、限られた人材ですので、そこを工夫しながらという形が、今のところの実態でございます。"},{"i":57,"speaker":"あべ委員","text":"今日はここまでにしておきますけれども、一つ課題として感じるところです。"},{"i":58,"speaker":"こんの委員長","text":"ほかにございますでしょうか。よろしいですか。\nほかにご発言がないようですので、以上で、本件および報告事項を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(3) 令和２年請願第１６号 「子どもたちの安全と学びの保障」に関する請願\n(2) 令和２年請願第１５号 「国に少人数学級を求める意見書」提出に関する請願\n(5) 令和２年陳情第５７号 すべての子どもが２０人学級で学べる環境をつくるための陳情"},{"i":59,"speaker":"こんの委員長","text":"次に、予定表の２の請願・陳情審査を行います。\n予定表では、(1)令和２年請願第１４号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年請願第１６号、「子どもたちの安全と学びの保障」に関する請願を議題に供します。また、本請願の請願項目の中に、少人数学級の内容が含まれることから、これに関連して、(2)令和２年請願第１５号、「国に少人数学級を求める意見書」提出に関する請願および(5)令和２年陳情第５７号、すべての子どもが２０人学級で学べる環境をつくるための陳情の２件を併せ、３件を一括議題に供し、採決はそれぞれ行います。\n３件とも初めての審査でありますので、書記に朗読をさせます。\n〔書記朗読〕\n〔緊急地震速報のため、朗読中断〕"},{"i":60,"speaker":"こんの委員長","text":"では、会議の運営上、休憩いたします。\n○午前１０時３２分休憩\n○午前１０時３５分再開"},{"i":61,"speaker":"こんの委員長","text":"今、調べていただきましたが、詳細は分からないということですが、外で聞こえているだけで、揺れてはいませんので、このまま再開をさせていただきます。\nそれでは引き続き、朗読をお願いいたします。\n〔書記朗読〕"},{"i":62,"speaker":"こんの委員長","text":"朗読が終わりました。\nそれでは、本件に関しまして、理事者よりご説明願います。"},{"i":63,"speaker":"安藤委員","text":"議事進行の関係なのですけれども、中途議決の関係もあって、結構項目も多いので、午前中だと中途半端になってしまうと思うので、こちらの審査なのですけれども、午後に回してもらえないかと思っております。"},{"i":64,"speaker":"こんの委員長","text":"時間的に、これから説明を受けて質疑に入ると、途中になってしまうと。午後の予定を考えると、１１時をめどに、こちらの会議を一旦止めさせていただくという予定でいますので、その時点で、あとは午後に回るという話になります。"},{"i":65,"speaker":"安藤委員","text":"１１時をめどにということなのですね。"},{"i":66,"speaker":"こんの委員長","text":"そうなのです。"},{"i":67,"speaker":"安藤委員","text":"かなりの人数の方が署名を提出されていると思うのですけれども、傍聴の関係もありまして、午後からの予定だと考えている方も結構いらっしゃるので、そういった関係もありますので、できれば午後からに割り切って配慮してもらえるとありがたいのですが、いかがでしょうか。"},{"i":68,"speaker":"こんの委員長","text":"傍聴者の関係は、すみません、会議の運営上、１１時をめどに進めますので、その時点で午後に回れば、それはそれですし、傍聴者云々に関して、私たちのこの会議を午後にするとか、それは申し訳ないですけれどもできませんので、一応申し上げるのは、１１時をめどにこれを進めていきます。ですから、今、理事者からご説明をいただきます。その時点で何分なのか、質疑に入ります。質疑も途中で止めるような形に多分なるでしょう。その分、残ったのは午後に回るということですので、ご理解いただければ。\n〔「どっちにしても午前では終わらないから、いいのでは」と呼ぶ者あり〕"},{"i":69,"speaker":"こんの委員長","text":"ただ、１１時で一旦止めますので、すみませんけれども、質問が長いと途中で止めさせていただくことだけご了承ください。よろしいでしょうか。"},{"i":70,"speaker":"安藤委員","text":"理解いたしました。"},{"i":71,"speaker":"こんの委員長","text":"それでは、本件に関しまして、理事者よりご説明願います。"},{"i":72,"speaker":"工藤指導課長","text":"それでは、まず私から、請願第１６号、「子どもたちの安全と学びの保障」に関する請願の請願項目の1)、2)、4)に関して説明させていただきます。\nでは、1)の品川区の授業時数についてでございますが、現在の区が定めております品川区立学校教育要領では、確かに１・２年生では、本区の教育の特色であります英語科あるいは市民科などの推進に必要な授業時数というのは、増やしているところではございますが、３年生以上につきましては、国の学習指導要領と同様の授業時数となっているところでございます。\nまた、２点目のところで、コロナ禍においての私どもの対応でございますが、国から通知も出たところでございますけれども、私どもでいえば、品川区立学校教育要領に定めている各教科の目標・ねらいに達するように授業を行っていただきたいというところ、また、標準授業時数を示しておりますが、それを下回ることによって、それに反したとは取り扱わないという旨を通知したところでございます。\nそれを受けて、各学校では分散登校時以降、学習を進めるに当たっては、教育課程届を出しているところでございますが、それの再編成を行い、各学校でそれぞれの学習の指導計画等を見直して、実際に指導していただいているところでございます。\n続きまして、4)子どもの心のケアのためというところでございますが、項目にございます、例えば養護教諭あるいはスクールカウンセラーも含めて、また担任または学年の教員、また、学校に勤務しています教職員全体が、チームとして子どもたちの様子を見るというところで対応に当たっているところでございます。また、養護教諭の増員につきましては、定数の配置というところに従って進めているところでございますので、定数配置によるというところでございます。"},{"i":73,"speaker":"篠田学務課長","text":"それでは私からは、請願第１６号、「子どもたちの安全と学びの保障」に関する請願の3)の３項目、子どもの安全と学びの保障のために、区独自の少人数学級を実現してくださいについて、それと、請願第１５号、「国に少人数学級を求める意見書」提出に関する請願、ならびに陳情第５７号、すべての子どもが２０人学級で学べる環境をつくるための陳情に関しまして、考え方を述べさせていただきます。\n現在、区では、国の公立義務教育諸学校の学級編制及び教職員定数の標準に関する法律、および都の学級編制の基準に基づきまして、小学校１・２年生および中学校７年生につきましては基本的に３５人、その他の学年につきましては４０人で学級編制を行っているところでございます。本件請願・陳情におきましては、少人数学級によるべきと述べられているところではございますけれども、私どもといたしましては、大人数の学級にも少人数の学級にも、それぞれよさや課題があると考えまして、これまでも学級編制とは別に、学級を分けた少人数学習や複数の指導者によるきめ細かい授業を展開するなど、必要な人員や予算を確保した上で、柔軟に状況に応じた対応をしてきているものでございます。\nしたがいまして、まずは現状の基準等にのっとりつつ、区としてできる限り工夫をしながら、子どもたちの学びを充実させていくことが肝要と考えまして、取り組んでいるところでございます。また、それは２０人学級ありきという形で取り組むべきものではないと考えているところでございます。\nなお、陳情におきまして指摘されているような世の中の動きがあることは、報道等により承知しているところではございますけれども、それらに関しましては法改正等があった場合には、それらを踏まえて対応してまいるということになります。"},{"i":74,"speaker":"矢部教育総合支援センター長","text":"私からは、請願第１６号の4)番の心のケアのスクールカウンセラーのみについてお答えいたします。\nスクールカウンセラーにつきましては、東京都が全区立学校に週１回、１日配置しております。本区におきましては、週２日配置の学校もございます。区としては、巡回相談員による定期的な訪問、心理士やスクールソーシャルワーカー、指導主事などで構成するＨＥＡＲＴＳによって、適時に対応しております。\nまた、児童・生徒から見れば、目安箱、学期１回の生活アンケート、相談電話など、様々な相談窓口があり、現在でも子どもの心のケアには効果的なアプローチができていると考えております。"},{"i":75,"speaker":"有馬庶務課長","text":"それでは私からは、請願第１６号、「子どもたちの安全と学びの保障」に関する請願の5)、子どもの安全対策に必要な用務主事を増員してくださいということにお答えいたします。\n現在学校では、登校時にサーモグラフィーで検温を行い、子どもたちはマスクを着用し、換気をしながら授業を行うなど、安全対策をしているところでございます。そのような中で、消毒の関係ですが、用務主事につきましては手すり、ドアノブ、スイッチ類を中心に行っております。以前は１日１回以上ということでございましたが、厚生労働省等の通知により、今は１日１回でよいという形になってございます。教室の机、椅子などは教員、あるいは掃除の時間に中学生などは生徒が行うなどのケースもあるということでございます。\n現在、用務主事とのヒアリングも随時行っておりますが、その消毒のやり方にペースをつかめている、慣れてきているということで、効率よく進めているということで、実際に増員してくれという声は聞いておりませんので、今のところ、増員をする予定はございません。"},{"i":76,"speaker":"こんの委員長","text":"説明が終わりました。\n一応、これから質疑に入っていくわけですが、先ほども申し上げたとおり、１１時をめどに会議を進めていきますので、時間的にお一人ぐらいかなと読ませていただきます。そのことをご考慮いただいて質疑をお願いいたします。\nそれでは、本請願・陳情につきまして、ご質疑、ご意見等がございましたら、ご発言願います。"},{"i":77,"speaker":"あべ委員","text":"では、今のご説明に沿って何点かお伺いしたいと思います。\nまず確認なのですけれども、国の基準が何時間だったか、今の時数は学年ごとに国でどのくらいの時数になっていましたか。それで、品川区の１・２年生の部分はプラス何時間になっていたか、一応、数字で確認をさせてください。\nそれから、コロナによって、本年度大体何時間ぐらいマイナスになっているか、これも学校ごとに少しずつ違いがあるかと思いますので、ざっくりで構いません。\nそれから、主に少人数学級に関しての請願・陳情だと思っておりますけれども、１・７年生が３５人になってから、何か変化あるいは効果というものを感じていらっしゃるか、であれば、その内容がいかがであるかを教えてください。\nそれから、スクールカウンセラー等々のお答えで、現在でも効果的なアプローチができていると。確かにいろいろなアプローチをされているのは承知しておりまして、いろいろな効果も上げていらっしゃるとは思うのですけれども、それが十分と思っているかどうかというのを教えてください。\nまずはそこまでお願いします。"},{"i":78,"speaker":"工藤指導課長","text":"それでは私から、授業時数のことについてお答えをさせていただきます。\nまず、１年生のところでございますが、国の学習指導要領は８５０時間でございます。それに対して、私どもの教育要領は９２５時間で、７５時間の増でございます。\n２年生につきましては、国が９１０時間に対して、私どもは９６０時間ということで、５０時間増でございます。\n３年生以上は国と同様でございますので、教育課程、私どもの教育要領の時数で申し上げますと、３年生が９８０時間、４年生から６年生までが１,０１５時間、また７年生から９年生が同じく１,０１５時間というところでございます。"},{"i":79,"speaker":"篠田学務課長","text":"少人数学級に関しまして、３５人の効果の部分でございます。\n基本的には、それをすることによって、学級編制上、そういった対応が非常に取りやすくなっているということもございますので、子どもたちにとっても比較的、少しでも少ない数での学級になるといったところでは、担任との関係といったところでは余裕があると思われるところでございます。"},{"i":80,"speaker":"矢部教育総合支援センター長","text":"６月前までのお休みのことだと思いますが、学校によって違いますが、１４０時間ほどマイナスになってございます。\nもう一つ、スクールカウンセラーが十分かということでありますが、本当に朝から晩まで、週１回でも週２回でも、スクールカウンセラーは丁寧に子どもたちに対応していまして、保護者の相談件数も多くて、スケジュールがぎっしりと詰まっておりますので、来ていただいた相談者については丁寧に対応できていると感じております。\nまた、小中の違いはありますが、やはり担任が中心になって相談業務をしておりますので、そことスクールカウンセラーや、こちらの巡回相談員、もちろん管理職、養護教諭と連携して、相談業務を行っております。"},{"i":81,"speaker":"あべ委員","text":"それぞれありがとうございました。\n少人数学級のところのご説明で、「そういったところで効果がある」の「そういった」ということの中身があまり見えてこなかったのですけれども、少しでも少ないと、担任との関係が良好になりやすいということで、数が少ないことによる一定の効果というのは、教育委員会でも認識されているのかなとは感じました。\nもちろん、それが全てではないですし、いろいろな編制でいろいろな特徴があるとは思いますけれども、国でも３０人ということを打ち出しているのは、それなりのメリットといいますか、現行の４０人よりも３０人のほうが、総合的に見てプラスが大きいと判断したからこそ、国も３０人と言い始めているのではないかと思うのです。\nそういう意味では、国が法改正をするなら従いますということだけではなくて、よりよい教育環境というのを品川区の教育委員会としてはどのように考えていらっしゃるかということを、もう少しお伺いできればと思います。\nそれから、スクールカウンセラーの件ですけれども、十分に仕事をされているか、それは一生懸命されていると思います。それが、学校や教室あるいは生徒にとって、これ以上何も足さなくても学校はパーフェクトに心のケアができているのかという、子どもの側にとって十分かという質問をしましたので、何か課題を感じているところがあれば教えてください。"},{"i":82,"speaker":"篠田学務課長","text":"今、委員のご指摘があったとおり、国では３０人学級という形で様々な動きがあるということは、承知しているところでございます。それは国なりに、様々なメリットを考えてということだと思うのですけれども、私どもとしましても、例えば中身に応じて、先ほども申し上げたとおり、クラスを２つに分けている少人数の学習ですとか、各校では様々な展開というのをこれまでしてきているところでございますので、制度が変われば、それに沿って対応していくのはもちろんでございますけれども、現状でもできる範囲で考えられることをやっているというところでございます。"},{"i":83,"speaker":"齋藤教育次長","text":"品川区の平均的な１クラス当たりの児童・生徒の数なのですが、小学校・義務教育学校前期課程だと３０人ぐらい、中学校・義務教育学校後期課程だと３１人ということになっております。創立記念日をやりますと、大体７０年以上ということで、ご案内のとおり、ベビーブームの世代に対応した学校ですので、基本的には３０人学級に準ずる形で学校経営はできていると考えております。\nただ、４０人のクラスが１クラスでもある学校は４分の１ぐらいありまして、この２０人学級をという話での陳情については、そこまでは物理的には難しいのですけれども、おおむね３０人、国が目指す方向ではできているし、品川区一貫教育の成果で連携したり、あるいは少人数学級指導だったりということで、きめ細かくできている。ここは少し強調させていただきたいと思います。"},{"i":84,"speaker":"矢部教育総合支援センター長","text":"スクールカウンセラーは十分かということでございますけれども、委員もご存じかもしれませんが、Ａさんという方が必ずしもＢ君と本当にぴったり気持ちが合うかというと、そうでない場合があります。ですから、複数回いても相談できない場合もあるということで、繰り返しになりますが、目安箱とかアンケートとか相談窓口、教育相談もセンターは行っておりますので、こちらを案内することで、様々な窓口があることが大切だと考えております。"},{"i":85,"speaker":"あべ委員","text":"まず学級人数は、平均でいうと大体３０人前後、そういう数字になると思うのですけれども、これは平均は平均で、学級編制の大きいところは大きいところで分けて考える必要があると思うのです。日本の小・中学校のクラスの平均でも、私が随分前に見たときでも二十二、三人ぐらいになっていたので、今はそれを切っているかもしれません。その中には、とても小さい学級もあれば、４０人学級のところもあって、あまり私は平均というのは関係ないと思っています。\nむしろ後半でおっしゃっていた、４分の１の学校が４０人になっているという。違いましたか。では、そこをもう一回。"},{"i":86,"speaker":"齋藤教育次長","text":"１クラスでも４０人のいる学校が４分の１で、ほとんどの学校では３０人学級となっています。"},{"i":87,"speaker":"あべ委員","text":"１クラスでも４分の１がということは、三十何人と４０人、学級数ではなくて、分母がですね。了解しました。\nいずれにせよ、４０人というと、今の感覚からいえば、かなり多いのだろうなという学校あるいは学級が、まだまだ残っているという意味では、今後ももう少し減らしていったほうがいいのではないか。昔の国研の調査でも、多分、学習の効率がいいのは、どうも２０人ぐらいではないかという結果も出ていたかと思います。\nただ、２０人にすれば、この陳情・請願にあるように、不登校や様々な課題が全て解決するかというと、私はそうはあまり思っていなくて、既存の全国の２０人程度の学校が、いろいろとそうした問題を持っていないかというと、そうではないので、ほかの格差もとてもたくさんあると思っております。\nちょっと話が前後してきましたけれども、そういった意味では、品川区としてはどの程度の規模で、例えば今のハードではなかなか実現はできないかもしれないけれども、このくらいを学習の最適人数だと、学級運営も含めて、教科の学習だけではなく運営も含めて、どのくらいにしていきたいという思いも持ちつつ、ただ、今はこういう状況だし、学校を急に倍増するわけにはいかないし、だから今はこうなのですという姿勢を持っていただければと思うのですけれども、ただ法改正で何人と言われたからこうしますというのでは、教育の一つの主体である教育委員会としては、私としては寂しいと思うのです。\nそういう議論というのは、教育委員会の中ではされないのでしょうか。子どもたちの学習環境として、何人ぐらいに持っていくほうが本当はいいというような議論というのは、あまり関心がないのでしょうか。そこの姿勢の部分をお伺いしたいというのが１点です。\nそれから、スクールカウンセラーについて、いろいろな相談窓口があるということがよりよいとおっしゃるのは、すごくよく分かります。一つの職種をただ増員すればいいと思っているわけではなく、むしろスクールソーシャルワーカーですとか、いろいろな立場の方が増えていけばいいなと私も思っております。\nなので、最初のご答弁で引っかかってしまったのが、既にできていると言われると、もうこれ以上改善する気はないのか、改善の余地はないと考えているのでしょうかという思いも込めて、質問させていただきましたので、それぞれお願いします。"},{"i":88,"speaker":"篠田学務課長","text":"教育委員会としての学級人数に関する考え方ということでございますけれども、私どもとしましては、基本的に、まずきちんと法にのっとった対応を取っていくのが第一だと考えております。したがいまして、学級編制に当たっては、そこを軸に置いた上で、個別の対応については、少人数での対応もできるとか、体制を取っているということでございますので、逆に言うと、何人であればいいという理想的な学級人数、固定したものがあるということではなくて、その場面に応じた柔軟な対応を取っていけるものが、今のところは一番ではないかと考えているところでございます。"},{"i":89,"speaker":"矢部教育総合支援センター長","text":"教育相談につきましては、これから子どもたちの実態把握をしっかりと常々しながら、きちんと対応できるように体制を整えてまいります。"},{"i":90,"speaker":"こんの委員長","text":"質疑の途中ですけれども、会議の運営上、暫時休憩いたします。\n○午前１１時００分休憩\n○午後 １時１２分再開"},{"i":91,"speaker":"こんの委員長","text":"それでは、休憩前に引き続き、文教委員会を再開いたします。\n休憩中に３名の方の傍聴申請がございますので、ご案内いたします。\nそれでは、予定表の２の請願・陳情審査から再開いたします。\n(3)令和２年請願第１６号、(2)令和２年請願第１５号および(5)令和２年陳情第５７号に関しまして、ご質疑、ご意見等がございましたら、ご発言願います。"},{"i":92,"speaker":"安藤委員","text":"まず、請願第１６号について、少し伺いたいのですけれども、午前中、品川と国の授業時間数についてご答弁がありましたが、さらに品川の標準時間を上回る時間数を設定している小学校もあるのです。例えば、ホームページに掲載されていますけれども、第三日野小学校のパンフレットには、１年生で９６３時間、２年生で９９９時間、３年生以上でも全学年で増やしています。こうした学校というのは何校ぐらいあるのでしょうか。また、どうしてこれが可能になるのかも伺いたいと思います。\nそれと、授業時間を多くしているというか、区自体が１・２年生については多くしているわけですけれども、その目的は何なのでしょうか。どんな教育学的な根拠に基づいていらっしゃるのかも伺います。\nあわせて、スクールカウンセラーなのですけれども、子どもが相談できるチャンネルは多いほうがいいというお話もありましたが、そうだと思います。ただでさえ子どものストレスが強まっていた中に、コロナ禍でさらに加速したわけで、子どもの声を受け止める大人の存在というのが子どもの周りにあるというのが、すごく大事だと思いまして、そんな中で、カウンセラーなのですけれども、今は非常勤で週に１日か２日しかいないという中で、十分な受皿になれるのかというのはあると思うのです。\nもちろん、頑張っていらっしゃるとは思いますが、たまにしか学校に来られないので、どういう状況なのかというのも日常的に把握できないですし、私は、常勤化で毎日いるという、常にその学校でどういうことが行われているか、子どもたちの様子を毎日見られる、その上で相談に乗る体制というのが、今こそ必要だと思うのですけれども、区の考えをお伺いします。"},{"i":93,"speaker":"工藤指導課長","text":"それでは、授業時数のことでございますけれども、午前中の段階で申し上げた私どもの教育要領上の標準授業時数を算出する上では、学校の教育課程では３５週と考えて組んでいるものでございます。これはあくまでも教育課程上、教育要領の目標・内容をしっかりと定着させるために必要な時間数ということで、それを定めているものでございます。\nただ、学校のほうは入学から、また始業式から、最後に終了の３月のところまでで、およそ４０週ほど学校の教育活動を行ってございます。そういう意味では、標準授業時数に加えて、学校でガイダンスであるとか、様々な特別活動等を行う時数を全て合わせると、標準授業時数を超えているというのは当然あろうことかと思います。ですから、そういったものを公表するというのはあろうかと思いますが、私どもは標準授業時数を上回って、教科の内容を定着させるために増やしているということではないと認識してございます。"},{"i":94,"speaker":"矢部教育総合支援センター長","text":"スクールカウンセラーの配置でございますが、繰り返しになりますが、東京都が配置しているということが１点。それと、先ほども区としては目安箱、生活アンケート、相談電話の窓口で対応したいということでございます。あくまでもお子さんの実態とか社会の状況なども踏まえて、丁寧に対応していきたいという考えです。"},{"i":95,"speaker":"安藤委員","text":"まずカウンセラーのほうで、都が配置しているかもしれませんけれども、不十分なのです。週に１日か２日しかいないとなると、なかなか学校でどういう教育活動が行われて、どういうところに子どもが悩んでいるかというのはつかみづらいというか、それは都であろうが区であろうが、今こういう状況なので、さらにストレスがかかっている状況なので、増やす対応というのは、区としても何か考えていく必要があると思うのですけれども、いかがでしょうか。\nそれと授業数のほうは、実際に区が示す標準授業数より増やしているというところが、何校あるのか、どれぐらいあるのかというのを伺ったので、それが分かればお答えいただきたいのと、あと、区自身が国の標準時間数を上回る標準時間数を設定しているわけですけれども、それの目的は何なのですかというのも伺ったので、お聞かせください。"},{"i":96,"speaker":"矢部教育総合支援センター長","text":"３点、私どもの担当で分かる範囲でお答えいたします。\n１点目の標準時間より超えている学校数については、今、手元にないので申し上げられませんけれども、基本的には子どもや地域の実態に応じて校長が作成しているものでございますので、例えば国際理解について少し手厚くしたいとか、この子どもたちにはこの時間ぐらいというのは、全部、枠の中で校長が判断しておりますので、多少ぎりぎりなところもあれば、多いところもあるというのが実態でございます。\nもう一つ、スクールカウンセラーについては、スクールカウンセラーは必ず記録票を取っておりますので、それを管理職とか、養護教諭とか、必要な関係、担任はもちろんですけれども、示して回覧しております。毎日常駐することで、必ずしもお子さんが全てそこのスクールカウンセラーにつながって、上手に対応できるかというのは、まだ分かりませんけれども、委員ご指摘のとおり検討していく、考えていくというのは、引き続き進めてまいりたいと考えております。"},{"i":97,"speaker":"工藤指導課長","text":"本区で国の学習指導要領を上回っているところは、本区一貫教育の特色であります英語科、市民科などの推進に必要な時数を増やしているというところでございます。"},{"i":98,"speaker":"安藤委員","text":"いろいろとご答弁いただきましたけれども、カウンセラーのほうはぜひ検討していっていただきたい。さらに大変なストレスがかかっている状況でありますので、なるべく時間をあまりかけずに、早急に検討して具体化していただきたいと要望いたします。\nそれと、コロナでできなかった不足の授業時間数はおよそ１４０時間というご答弁が午前中にありましたけれども、そういう状況で区教委は、今年度の年間指導計画は今年度中に終えて、授業の目当ては達成するようにという通達だったり、また、罰則はないというお話でしたけれども、標準時間数にできる限り近づけるという方針を出しております。\n１４０時間ができなかったわけですけれども、それを取り戻すためには、各学校は７時間授業の実施や行事の削減など、子どもにしわ寄せが来ざるを得なくなる、そういう状況に追い込まれるということは明らかなのではないか。こうした方針で区教委が現場を追い込んだ以上、自らの方針が子どもにどんなしわ寄せを生み出したのかというのは、私は把握・認識する責任があるのではないかと思います。\nまず伺いたいのは、今年度中に、コロナで失われた１４０時間を全て取り戻す学校というのは、どれぐらい生まれているのでしょうか。学校数や全体の何割ぐらいかを教えてください。\nそれと２点目は、１４０時間を確保するための子どもへのしわ寄せの実態について、そのために削減された行事や活動などがあるのかを伺いたいというのが２点目です。\nまた、７時間授業の実施というのは何校で行われたのか、全体の何割ぐらいで行われたのでしょうか。それも伺いたいと思います。"},{"i":99,"speaker":"矢部教育総合支援センター長","text":"順不同になりますが、３点いただいたかと存じます。\n初めに、削減された内容はどのようなものかということで、区では連合行事が一番大きなところでございまして、そこで内容としては削減の形です。ただし、もうご承知のことと存じますが、各学校で運動会に代わる代替の活動をしてみたり、学校の校内でできることを子どもたちが相互に工夫して、何かレクリエーションにつなげているというのは、それぞれ学校で工夫してやっております。\nまた、授業については、数字もありましたが、基本的にはどこの学校も追いついていると聞いておりますので、今後まだこれからのこともございますが、現状では十分活動はできていると考えています。\nまた、基本的に学習のほうも、全ての時間をきちんとやることができないのですから、一つ一つの単元という、例えば算数の小数だったら小数を、本当は１０時間でやらなければいけないところを９時間や８時間でやっているということで、ねらいを達成するようにしています。例えば、社会科の小学校３年生には、消防と警察を７時間ずつやって１４時間という単元がございますが、これはねらいはほぼ同じで、組織的・計画的にしているという内容などを加味すれば、７時間・３時間で消防・警察を分けて１０時間で進めているところもございます。ねらいは達成してございますので、一つ精選という言葉を加えさせていただければ、このような方法もあると考えております。\nあと、実態をどう捉えたらいいかというお話でしたが、基本的には指導主事に担当の学校がございますので、月一、二回は巡って授業を観察しておりますので、子どもたちが慌てて授業をしていないかとか、どのくらい学校で考えて活動させているかということを把握してございます。"},{"i":100,"speaker":"安藤委員","text":"この時点で１４０時間は既に取り戻しているのがほとんどという状況なのかなと、答弁では伺いましたけれども、それをどう見るかということなのですが、まだ３学期にもなっていない時点で、もう取り戻したということになると、これまで相当な無理をしたのかなと思ってしまうのです。子どもにそれが短時間での詰め込みという形でしわ寄せにならないことを祈っていたわけですけれども、伺った中で、７時間授業が実施された学校というのは何校なのか、大体全体の何割ぐらいだったのかというのを伺ったので、それは答弁がなかったので、聞かせていただきたいと思います。\nそれと、請願第１５号と陳情第５７号なのですけれども、これは少人数学級に関するものなのですが、まず請願第１５号に関しては、議会として意見書を上げてほしいという請願なので、午前中にもやり取りがありましたけれども、今、品川区議会が子どもの立場に立って主体性を発揮することが重要なのではないかと。少人数学級を求める意見書というのは全国では５３４の地方議会で採択をされまして、２３区でも中野区、豊島区が採択をしております。ぜひ各委員の皆さんのご意見も聴きたいですし、議論を深められればという思いがあります。\n質疑に移るのですけれども、午前中、少人数学級の効果についての質疑がありましたが、品川区の答弁を聞いていますと、小規模も大規模もメリット・デメリットがあるのだということですとか、何人という理想的な人数があるわけではなくて、場面に応じて対応しているというご答弁で、少人数学級の流れといいますか、今の前向きな流れというのを全然評価しようとしていないというのが、すごく残念です。\nでも、分散登校時にありましたけれども、現場や子どもは少人数での学校生活、学習を実際に体験したわけです。そのメリットというのを事実として体感したわけです。だから改めて、少人数学級をやってほしいという声が上がっているのだと私は思います。\n質問ですけれども、全国的にも学校再開時の少人数の分散登校時には、不登校の児童・生徒が減ったという報告もあるのですが、品川では実際、この辺はどうだったのかを伺いたいと思います。これが１点です。\nまた、品川の教師から私も、分散登校時に子どもの表情ですとか、理解できているかとか、できていないかというのが、手に取るように分かると。そのすばらしさ、効果というのを実感したという話も伺うのです。品川区はそういう教師の声というのを聞いたことがあるのかないのか、伺いたいと思います。それが２番目です。\n３点目は、一方で先ほど区は、少人数学級はあまり評価されないのですけれども、クラスを２つに分けたり、様々な対応をしているというご答弁もおっしゃっておりました。これは具体的にはどういう対応なのでしょうか、伺いたいと思います。"},{"i":101,"speaker":"矢部教育総合支援センター長","text":"７時間授業については、答弁漏れで失礼しました。あともう一つは、不登校が減ったかどうかということと、先生方の声ということを私のほうでお答えいたします。\n７時間授業のほうは、当初いただいていた数からすると、半数程度と認識していますが、既に学校では学習が追いついたということで、３学期は戻そうと考えているという声も聞いてございます。\nもう１点、６月あたりの登校し出した分散登校のときの不登校ですけれども、今まで出てこなかった子が出てきているという実態はございます。ただ、その後、人数が多いというよりは、様々、行事もなくなっているのですけれども、変化もありましたので、そこに子どもたちがうまくついていけないということは聞いておりますので、また少し数としては戻ってきてございます。\nあと、先生方の声でございますが、委員がおっしゃったような声もあると思いますけれども、子どもたちが少なくて寂しいとか、授業が盛り上がらないという声も聞いてございます。"},{"i":102,"speaker":"工藤指導課長","text":"授業の工夫のところでございますが、私どもは個に応じた丁寧な対応をするため、例えば算数、数学などを少人数、例えば加配をいただいている場合は、２学級を３つに分ける、いわゆる３展開という言い方をいたしますが、そこに例えば区費講師をつけられる場合は、さらにもう１展開ができるとかということで、少人数指導を充実させるような施策を行っているというところがございます。"},{"i":103,"speaker":"安藤委員","text":"分かりました。そういうご答弁をいただきました。\n最後のところですけれども、対応というのは、そうではないかと思ったのですが、習熟度別学習だと思うのです。これはごく限られた教科で、しかも習熟度別学習というのが少人数でやることでの丁寧さというのはあるとおっしゃるのでしょうけれども、また別な問題があるというのは、当然、教育学の中でも指摘はされていると思うのですが、子ども同士の情緒的な問題がいろいろとあるというのを私は認識しています。習熟度別というのはやめるべきだと私は思っています。\nこの対応というのは、区もやっているのだと、場面に応じてやっているのだと度々言いますけれども、この対応というのは習熟度別で、学校生活を送る単位としてのクラスというのを、そもそもふだんから少人数にするということとは全く違うことだと思うのですが、いかがお考えでしょうか、伺いたいと思います。"},{"i":104,"speaker":"工藤指導課長","text":"先ほど申し上げた少人数指導、いわゆる習熟度別指導も行ってございますが、そのほかに私ども区といたしましては指導助手ということで、各教科担任の授業の中に指導助手、それぞれ個別に児童・生徒を見るような人材も配置してございますので、そういった場合は、主となる担任の指導あるいは教科担当の指導に加えて、個に応じた指導もできるような体制を取っておりますので、そういった意味では、個に応じた丁寧な授業が行えるような体制を取っているというところでございます。"},{"i":105,"speaker":"安藤委員","text":"指導助手という話がありましたけれども、それでも学校生活を送る単位としてのクラスは変わらないわけで、場面場面で学習面のごく一部で、かなり個に応じた対応を取られる場面もあるかもしれないのですが、私はそれと少人数学級というのは違うと思うのです。\n今回、請願を出されている「少人数学級を求める品川連絡会」さんからお手紙をいただきましたけれども、各委員にも届いているのではないかと思うのですが、この中にチラシが入っていまして、少人数学級の意義と思いが書かれていました。\nこういうことだと思うのです。一つは、少人数なら一人ひとりが活躍する場が増えますと。発言や発表、理科の実験、音楽の楽器演奏、体育の跳び箱や鉄棒の練習など、体験したり学習活動をしたりする機会や時間が増えると。子どもの学習体験を豊かにするのだ、活躍できるのだと書いております。\n同時に、こういう子どもの活躍をサポートする教師の側にとっても、このチラシに書いてあるのですけれども、先生から一人ひとりの子どもの様子がよく見えると。元気があるかないか、学習が理解できていないか、それはとても大切なことなのだと書いてありまして、子どもをさらにきめ細かく全力で支援できるということだと思います。\n私は先ほどの習熟度別ですとか指導助手では、このような少人数学級が持つ教育における本質的な生活面・学習面のメリットの代わりにはならないと思うのですけれどもいかがでしょうか、伺いたいと思います。"},{"i":106,"speaker":"矢部教育総合支援センター長","text":"これまでも少人数がいけないということは一言もなく、それぞれ大人数も少人数もよさがあるとお伝えしてきたというつもりでございます。少人数には先ほどのお話のとおり、きめ細かにできるとか、お子さんの様子が見られるとか、発言回数が増えるということもございます。\nただ、様々な意見が出にくかったり、例えば跳び箱でもマット運動でも、少人数だとあっという間に終わってしまいますので、そういった運動面のこともありますし、様々、デメリットは出てしまうわけなのです。また、友達関係も決まってしまったりすると、うまく交流できなくなったりする子もいるかもしれません。そういったデメリットもある。\nだけれども、大人数については、先ほど委員がおっしゃったようなこともございますので、裏腹のところで、本区の現状としては、大人数と少人数をバランスよくやりながら、そのメリットとデメリットを見極めて進めていくというところがスタンスでございます。"},{"i":107,"speaker":"安藤委員","text":"やはり私は、大規模によるメリットというのを具体的に何と考えているのかを伺いたいのですけれども、後で聞かせてください。仮にそれがあったとしても、学級生活集団、生活を送る単位のクラスを、今が多過ぎるので、それを少なくしていくということについては、はるかにメリットのほうが大きいと私は思います。\n学級規模でそういった考えが趨勢なので、恐らく、発達した資本主義国では１学級２０人から３０人が主流だと。日本のように上限が４０人というのは考えられないという状況になっているわけです。例えばアメリカは、州によって違うようですけれども、フロリダでは１から３学年で１８人、４から８学年で２２人、９から１２学年で２５人と。フィンランドでは、国基準で地方分権がなくなってしまったようですけれども、それでも２５人以下というのが当たり前だと。そういう流れになっているのだと思います。子どもにとっていいからということだと私は思います。\n同時に、こういった観点もあるのではないかと。多様な個人を尊重する今の時代の流れがあると思うのですけれども、少人数学級を求める声というのは、そういう時代の流れとも響き合っているのではないかと。\n例えば、うちの共産党の志位委員長が少人数学級の提案をツイッター上でしたときに、ある母親からのこういう書き込みがあったのです。子どもたちの学びの多様性に応えられる教育を可能にするために、少人数学級は重要な第一歩だと思うと。それぞれの子を、子どもという固まりや集合体として教育するのではなくて、Ａ君、Ｂさん、Ｃちゃん、それぞれの成長を支える教育であってほしいという書き込みがありました。子どもの成長というのは多様なもので、多様な子どもの成長、その成長を理解する側がそれを支えようとすれば、私は少人数で教える以外にないと思うのです。\nですから、伺いたいのは、多様な子ども一人ひとりの個性を理解して、それを支えるのが私は教育の理想だと思いますけれども、今はそれが強く求められる時代になっていると思いますが、そういう実現のためには、少人数学級の実施というのは、私はプラスになると思うのです。そういう認識でよろしいでしょうか。品川区としても、区教委としても、こういう時代の要請、多様性を尊重して一人ひとりに合わせていくという教育の実現に、少人数学級の実施というのは、少なくともプラスになるということについては認識を共有できるのでしょうか、伺いたいと思います。"},{"i":108,"speaker":"矢部教育総合支援センター長","text":"初めに、大人数のメリットということでご質問があったところでございます。繰り返しのところもありますが、ご了承ください。多様な意見が出るということが１点。もう一つは、その中でも、例えば音楽や体育や図工などの教科においても、様々な表現や技能を見聞きすることで、友達の新たなよさを発見できたり、自らも新たな表現や挑戦する気持ち、またアイデア等が生まれることが期待できます。\nまた、大行事、運動会、学芸会、合唱コンクールなど、クラス単位で参加することが多い行事についても、その一体感、全体のエネルギーなど、集団での力を体感できる機会と感じています。子どもたちは現状、これらのことを繰り返していますので、その中で、集団で学ぶよさとか、友達のよさということを感じていると考えてございます。\nまた、生活面については、一日のほとんどを、委員おっしゃったようにクラス単位で生活しますので、学級集団はとても重要な教育環境だと考えております。朝の挨拶からグループ学習、給食や掃除まで、大人数によって関わる仲間が多いということで、多くの考え方に接することになります。これは先ほどのご質問にも関わりますが、多様性を見る、または認める、理解するという機会にもなると考えています。時には意見が対立することもあると思いますが、それをフォローする子どもたちもいます。そこで傷ついたり、友達と友情を深めたり、そんな機会でもある。それが学校の貴重な経験だと考えています。これが大人数のメリットです。\nまた、重複しますが、多様性を大事にするということは、本当に私どもも重要なことだと考えてございます。人数が多くても少なくても、多様性を認めるということは大変大事で、そのケースが多いといいますか、人数が多くなれば分母が多いわけですから、出会うことも多くなります。それを皆で一緒に考えて理解するという経験も、大人数の中でもできると考えております。"},{"i":109,"speaker":"こんの委員長","text":"質問を受ける前に、一言申し上げます。繰り返しの答弁、繰り返しの質問が続いていると思われますので、質問の内容を変えて質問してください。質問をまとめていただきたいと思います。"},{"i":110,"speaker":"安藤委員","text":"後日、議事録を確認してもらえばと思いますけれども、同じ趣旨の質問をしていることはないと思いますが、最後の意見に対しては、意見で終わりますけれども、大人数であっても少人数であっても多様性を認めることはできるとおっしゃいますが、一人ひとりの子どもたちが見られたり、支援されたり、あるいは発言できたり、表現できたりという機会が多いというのが、一人ひとりが活躍できるという点で、少人数のメリットというのは相当大きなものがあると思います。\n私は、こっちもいい、こっちもいいという考えに立ってほしくないと思いますので、ぜひ品川区議会としましては、しっかりと国に対して、今、大きな国の流れにもなって、文科省の大臣自らも決意を持って頑張りたいという発言もしていますし、世界の趨勢でもありますので、ぜひ品川区議会からも、少人数学級を前に進めるという発信ができたらと思います。意見です。"},{"i":111,"speaker":"たけうち委員","text":"請願の第１６号のほうですが、先ほど午前中の答弁、やり取りで、5)番、用務主事の増員ということについては、学校から特に声は聞いていないというお話があったと思うのですが、1)から4)の、今、それぞれ質疑がありましたけれども、保護者の方とか、子どもたちからというのはないのかもしれませんが、主に保護者の方、また学校側から、例えばスクールカウンセラー、また少人数学級、それぞれの要望の声みたいなものが、どの程度上がっているのかというのが分かれば教えてください。"},{"i":112,"speaker":"工藤指導課長","text":"私どもの教育要領に関するところでいきますと、例えば英語科を１・２年生から教科として行っているところでございますが、これまで行っている保護者アンケート、あるいは児童・生徒アンケート等でも、肯定的な回答をいただいているところです。また今回、国の改訂に併せて私どもも改訂する中では、現場の教職員からの意見を伺うなどしたときに、そういったところで、特に英語についても活動を中心に行っている慣れ親しむ時期に、それを時数の中ではゆっくりとできていくというところで、評価をいただいたりしています。ですので、児童に対しては過度な負担になっていないというところを検証しながら進めているところでございます。"},{"i":113,"speaker":"篠田学務課長","text":"少人数学級に関する学校からの声ということでございますけれども、学校から、学級編制自体を小さくしてほしいという声は特段聞いていないです。ただ、先ほどからお話させていただいているとおり、少人数展開にしたりというときに、教室がいろいろと必要だとか、そういった設備面での要望というのはありますけれども、学級編制自体を少人数にしてほしいという声は、こちらには届いているものではございません。"},{"i":114,"speaker":"矢部教育総合支援センター長","text":"スクールカウンセラーについてでございますが、主に学校からの評価をこちらは受けてございますが、校長からそれの頻度については、要望は特段ございません。また、保護者からの声もございませんが、直接スクールカウンセラーを受けてもいいような事情をこちらが受け取るときがありますので、スクールカウンセラーにつなぐ、また、あまり合わないということであれば、こちらの教育相談のほうで受け取ったり、指導主事が対応したりしてございます。"},{"i":115,"speaker":"たけうち委員","text":"それぞれありがとうございました。さっきから大人数、少人数と、どこを基準に大人数、少人数にすればいいのかなと。前もお話ししたけれども、昔はよく３０人と言っていて、実質、３０人がいいか悪いかはあれだけれども、３０人になった途端、今度は２０人と。今度２０人になったら、１０人にすればいいのかと。どこまで行けばいいのか。そうしたら家庭教師がいいのではないかとなってしまうのかなと。\nさっきいろいろとあったとおり、大きな単位でやる場合のメリットもあれば、小さい単位でやるもののメリットもあるでしょうし、いろいろとあるけれども、発言の機会が増える、一人ひとりに目が行く、おっしゃるとおりかもしれません。ただ一方で、ちょっとなじめない子とか、人数が少なくなることによって、逆にプレッシャーを感じてしまうということもあるでしょうし、それは理屈を言えば、いろいろな言い方はあると思う。多い人数も少ない人数も、両面あると私は思うのです。\nだから、数で決めるということは、私はどうかなと思いますけれども、後でそれを踏まえて検討したいと思います。ありがとうございました。"},{"i":116,"speaker":"筒井委員","text":"請願第１６号についてです。１番で、授業時数を削減してくださいということなのですけれども、実際、授業時数を削減してしまったら、教育効果に与える影響というのはあるのでしょうか。ほかの学年のお子さんたちとの公平性、同じような内容の授業を受けなければいけないと思っているのですけれども、実際に削減してしまったら、どういう影響があるのでしょうか。"},{"i":117,"speaker":"工藤指導課長","text":"実際にという仮定のお話ではございますけれども、私どもが定めている標準授業時数というのは、国の学習指導要領、また、その内容はもちろん踏襲してございますが、私どもの教育要領で定めている学習内容を定着させるのに必要な時数ということですので、それを削減するということは、少ない時数の中で目標・ねらいを達成させなければいけないということで、そういった意味での圧迫にはなろうかと思います。"},{"i":118,"speaker":"筒井委員","text":"分かりました。\nまた、消毒作業のための用務主事も増員をということなのですけれども、先ほど増員してほしいという声はないというのがありましたが、その辺り、やはりコロナ対策に必要だと思うのですけれども、改めて確認ですが、用務主事の増員はする必要はない、十分消毒はできているということでよろしいでしょうか。当然、予算で人件費が、用務主事を増員するとかかってしまうのですけれども、人件費はどこが増員というお求めなのか分からないのですが、かかるとしたら人件費と、繰り返しになりますけれども、現状の対応で消毒は十分なのか、この２点をお伺いしたいと思います。"},{"i":119,"speaker":"有馬庶務課長","text":"用務主事の関係ですけれども、先ほども申し上げましたとおり、日々の業務の中で、消毒作業ということがある程度ルーチン化されてきて、用務の方は慣れているということがございます。その結果、私のほうも、昨年の８月、９月、１０月と、今年の８月、９月、１０月と、用務の方の超勤時間がどのように変化しているのか見ておりますけれども、基本的には全体で５０時間いっていないと。それは昨年も今年も同じということで、大きな変化はないということですので、特に増員するまでのことはなく、きちんと効率よく学校の中では仕事がされていると考えております。\nそのためには、教員の方たちやスクールサポートスタッフの方たちも、職員室だとか、そういうところで当然協力してもらっているとは思いますけれども、基本的な手すり、ドアノブ、スイッチといったところは、きちんと用務の方のほうで対応できて、それで一応進んでいるということですので、今のところ、増員はなくてもいけると考えているところでございます。"},{"i":120,"speaker":"筒井委員","text":"費用対効果というのも考えなくてはいけないのかなと思っております。消毒は十分できているということで、分かりました。\n続いて、請願第１５号と陳情第５７号についてお伺いしますけれども、２０人学級にしてくださいということで、これは第３回定例会でも同様のものが出てきたと思いますけれども、その際は、物理的に教室とかを調整するのが難しいというお答えで、そこから約３か月で、それが急速に環境が変わるわけではないとは思っております。\nただ、今、文部科学大臣が、３０人学級を目指すべきだということもおっしゃられているので、それに対して財務省が反論をされてというところで、３０人ということで相当争点になっているのかなと思うのですけれども、ただ、所管省の文部科学省が３０人学級ということになっているので、将来的には少人数学級の方向に行くのかなと思っているのですが、現在、教室の改築とか、空き部屋、空いている施設の活用とかで、実際、少人数学級を目指すということは可能なのでしょうか。これで教室が狭くなって、先生が通路が狭いので通れなくなっているというお声も聞いておりますので、そこの辺りの改善を、なるべく現在の環境で工夫してできることはないのかなと思っているのですけれども、その辺りについて、どうお考えなのでしょうか。"},{"i":121,"speaker":"篠田学務課長","text":"現状の学校施設におきまして、仮に少人数が少し進んで、一つは教室数が足りるかどうかという話になってくると思うのですけれども、現状では３０人学級みたいな形になってきたときに、まだ詳細な試算をしているところではございませんが、幾つか各学校で空いている、例えば多目的室ですとか、まだランチルームを持っている学校もありますので、そういった学校では転用して普通教室としていけば、おおむねは足りるのかなと思っています。\nただ、相当厳しくなっている学校もございますので、そういった学校に関しては、新たに外に何らかの形で、仮設の校舎みたいなものを造るのかどうかといったことも含めて、検討していく必要はあろうかと考えているところでございます。現状、廊下云々の話もございましたけれども、できるだけ教育環境を整えながら、普通教室もきちんと充足をさせているということで、今のところ対応しているものでございます。"},{"i":122,"speaker":"筒井委員","text":"分かりました。３０人学級ということになっていくのかなと思いますし、実際に現在生じている先生たちの、通路が狭いというお悩みとかがありますので、今おっしゃられたように、できる限り転用とか、そうした工夫をしていただいて、今ある課題はぜひとも解決していっていただきたいと考えております。\nそれで、２０人ということなのですけれども、３０人で今、国が相当そのことで争点になっているときに、いきなり２０人ということなのですが、２０人学級というのは今の品川区で、やろうと思えば可能なのでしょうか。"},{"i":123,"speaker":"篠田学務課長","text":"２０人というのは、学級編制を２０人にした場合という形で捉えますと、これは第３回定例会のときにもご答弁申し上げたとおり、単純にいけば、教室数が倍近くになりますという話でございますので、今ある数、七百何十教室を、一気に１,５００ぐらいの数にするというのは、現実的には不可能であると言っても差し支えないかと思っているところでございます。"},{"i":124,"speaker":"こんの委員長","text":"ほかにございますでしょうか。よろしいですか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれではまず、令和２年請願第１６号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言ください。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、自民党からお願いします。"},{"i":125,"speaker":"芹澤副委員長","text":"本日、結論を出すで、不採択でお願いします。\nそれぞれの項目をご説明いただきましたけれども、中には既に実現しているものと、あとは今、お話がありましたとおり、実現がなかなか不可能に近いものが多くありますので、不採択でお願いします。"},{"i":126,"speaker":"せお委員","text":"本日、結論を出すで、不採択でお願いします。\n今、自民党もおっしゃっていたように、私たちの会派でも、一部実現しているものもありますし、不可能なものもありますということで、今の品川区の現状では不可能かなということで、不採択でお願いします。"},{"i":127,"speaker":"たけうち委員","text":"不採択でお願いします。\n質疑で確認させていただいたとおり、そういう保護者、また関係の声というのはそれほど多くない、もしくはほとんどないと承っているところでございますし、また、人数に関して言えば、少人数というのは確かにあるでしょうけれども、区独自でという、どこを目指しているのかがよく分からない部分もあります。そういったことで、不採択ということでお願いいたします。"},{"i":128,"speaker":"安藤委員","text":"本日、結論を出すです。採択ですけれども、これは別に不可能な項目は一つもないと思うのです。少人数学級を、ここには２０人と書いていないですし、区独自にどのような少人数学級にしていくか、一歩踏み出すということが大事だと思います。少人数学級の流れができている中で、区が子どもたちの立場に立って、できることをやっていくということは、すごく必要なことだと思います。\nあと、ほかの様々な項目についても、これまでも国連子どもの権利委員会から、既に再三にわたり、過度な競争教育が指摘をされて、その下での子どもの権利が危機になっているということが指摘をされてきていましたけれども、その矛盾がこの中で一層浮き彫りになっているわけですから、加速しているわけですから、どの子も安全に楽しく学べる環境を保障するために、私は採択すべき内容だと思います。"},{"i":129,"speaker":"筒井委員","text":"本日、結論を出すで、不採択でお願いいたします。\n必要な授業数はやらなくてはいけないですし、あと、様々、先ほど答弁で確認させていただきました。それを踏まえて、今回は不採択とさせていただきます。"},{"i":130,"speaker":"あべ委員","text":"本日、結論を出すということで、不採択でお願いします。\n項目は５つに分かれておりますけれども、特に今年はコロナということですので、授業の時数が非常にイレギュラーなことになりました。なので、むしろ子どもたちの学力面での不安ですとか、こうした中でも思い出づくりもしていきたいとか、いろいろな思いが子どもたちにあると思いますので、それらに応えるような形で授業を組んでいただいて、それが結果として何時間になるかというのは、また子どもたちの状況によっても変わってくるかと思いますけれども、そこは丁寧に授業の再編成をしていただければと思っております。\nそれから、少人数学級については今、国がちょうど３０人学級というのを打ち出しているところで、まずはこの流れで、先ほど午前中にも少し言いましたけれども、日本の多くの学校は既に３０人以下の学級になっていて、まさにこれは都市部のこれからの問題だと思っております。それに近づけるために、むしろ国の方針と流れを一緒にして、品川区としてどこまでできるか、その方針に近づけることができるか、それは学級編制だけではなくて、加配をその分もらうとか、そういったことも含めて、区としても動いていただければと思います。\nスクールカウンセラーについては、午前中も言いましたけれども、現状で満足することはなく、様々な心のケアの仕組みを整えていただきたいと思いますし、それから５番目のほうも、学校の教職員も用務主事も、増務になっているのは確実だと思います。超勤も調べていただいているということですけれども、それがきちんと仕事の実態を反映しているのかどうかも含めて、適切に対応していただければと思います。\n全体としては、現在の実施されている方向で進めていただければと思います。"},{"i":131,"speaker":"横山委員","text":"結論を出すで、不採択でお願いします。\nそれぞれの質疑ですとか、ご答弁をお伺いしてまいりましたが、特に学級編制については、法の規定や都の基準にのっとって対応していただいて、教える教科、単元、内容によって、少人数指導や習熟度別学習などを適切に実施していただきたいと私は考えております。"},{"i":132,"speaker":"こんの委員長","text":"それでは、令和２年請願第１６号につきまして、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":133,"speaker":"こんの委員長","text":"それでは、令和２年請願第１６号は、結論を出すことに決定いたしました。\n先ほどの質疑でそれぞれの方のご意見を伺いましたので、令和２年請願第１６号につきましては、挙手により採決を行います。\nお諮りいたします。\n令和２年請願第１６号、「子どもたちの安全と学びの保障」に関する請願を採択することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":134,"speaker":"こんの委員長","text":"賛成者少数でございます。\nよって、本件は不採択と決定いたしました。\n次に、令和２年請願第１５号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、自民党からお願いします。"},{"i":135,"speaker":"芹澤副委員長","text":"本日、結論を出すで、同じく不採択でお願いします。\n少人数学級というところに関しては、自民党も国政のほうで決議を出していて、３０人というのは検討しているところであります。そういう意味では、３０人の少人数学級は、わざわざ意見書を出すまでもなく動いているかなと思っていますが、ここに、１学級の人数を２０人程度にすることは必須の条件と書いてあって、２０人というのは、どのエビデンスを持って出てきたのかがまだ分かりませんので、不採択ということでお願いします。"},{"i":136,"speaker":"せお委員","text":"本日、結論を出すで、不採択でお願いします。\n先ほど質疑でもありましたが、３０人ですけれども、文科省で少人数という発言もあって、あと答弁で、法改正があったら対応していくという話がありましたが、そこら辺は長期的なビジョンとかを持って学級編制を考えて、シミュレーションとかだけはしておいてほしいと思っています。ただ、現実、２０人というのは不可能に近いと思いますので、不採択でお願いします。"},{"i":137,"speaker":"たけうち委員","text":"本日、結論を出す、不採択でお願いします。\n前回のときに出てきた内容と同じで、答えも同じですけれども、やはり２０人というところに、それが了解できないと思っていますので、不採択です。"},{"i":138,"speaker":"安藤委員","text":"本日、結論を出すで、採択なのですけれども、まず２０人というところなのですが、先ほど２０人の学級編制でということでお答えがありましたけれども、２０人程度にすると書いているので、今の標準のルールを２０人にすることで、２１人になったら１１人と１０人になるという意味では私はないと、ここは読み取れます。なおかつ、２０人程度の学級にすることを展望していくということは、私は大事なことだと思います。\nなぜならば、コロナの問題でいうと、２０人ぐらいにしないと、正直、国が言っている「１ｍは少なくとも離れましょう」みたいなことは、実現できないわけです。何で子どもたちだけが、アナウンサーがテレビで離れてしゃべっていますけれども、そういう場面を見せつけられているのに、自分たちはずっとソーシャルディスタンスを取れないのだという問題もありますし、欧米などを見てみますと、子どもの規模をもっと少なくして、教育の質の面からも、そういう流れが出ていますので、私は２０人学級を展望して、少人数学級の実現を強く求める意見書を出していくということは、非常に大事なことだと思いますので、採択を主張したいと思います。"},{"i":139,"speaker":"筒井委員","text":"本日、結論を出すで、不採択でお願いします。\n先ほど述べましたとおり、今現在、国のほうで文部科学省と、それに対して財務省が３０人学級に対して反発をしているという状況で、３０人になるかどうかというのが専らの課題で、そこに急に２０人という数字を出していくというのは、かなり非現実的であり、さらに、２０人学級ということを展望といっても、物理的に現在の体制では不可能ということでもあります。\nよって、不採択とさせていただきますけれども、先ほど述べましたとおり、現在起きている課題の解決のためと、少なくとも３０人学級に向けての備え、準備という点で、今できること、転用とか、そうした工夫をぜひ検討していっていただきたいと考えております。"},{"i":140,"speaker":"あべ委員","text":"本日、結論を出すということで、不採択でお願いします。\n先ほどとちょっと重なりますけれども、今、国が３０人学級というのを打ち出しているということです。国が３０人をここで打ち出すというのは、私はすごく勇気の要ることだったと思うのです。なので、その目標に対して、むしろ自治体というか、地方の教育委員会としては、別の目標ではなくて同じ目標、同じ３０人学級という目標で、国だけではなくて、地方もこれを応援しているということで、そういう形で声を上げていっていただきたいなと。\n単に国が決めたらやりますではなくて、地方としても３０人というのは歓迎するという形で、同じ目標で動いていただけるといいなと思いますし、それから先、３０人よりさらに減らしていくかどうかというのは、今、日本の学級編制は上限規定になっているので、それを３０人よりさらに、上限規定のままで減らすというのは、あまりにも学級編制が小さくなり過ぎる可能性があるので、そこはまた数字ではない、質的な物の考え方が変わったら、その先もあるかもしれないとは思いますけれども、それは今の議論ではないかなと思います。"},{"i":141,"speaker":"横山委員","text":"結論を出すで、不採択です。理由は先ほど述べたとおりです。"},{"i":142,"speaker":"こんの委員長","text":"それではまず、令和２年請願第１５号につきまして、結論を出すとの意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":143,"speaker":"こんの委員長","text":"それでは、令和２年請願第１５号は、結論を出すことに決定いたしました。\n先ほどの質疑で、それぞれの方のご意見を伺いましたので、令和２年請願第１５号につきましては、挙手により採決を行います。\nお諮りいたします。\n令和２年請願第１５号、「国に少人数学級を求める意見書」提出に関する請願を採択することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":144,"speaker":"こんの委員長","text":"賛成者少数でございます。\nよって、本件は不採択と決定いたしました。\n次に、令和２年陳情第５７号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、自民党からお願いします。"},{"i":145,"speaker":"芹澤副委員長","text":"本日、結論を出すで、不採択でお願いします。内容は先ほどと同じですので、省略をいたします。"},{"i":146,"speaker":"せお委員","text":"本日、結論を出すで、不採択でお願いします。理由は、先ほどの請願第１５号と同じです。"},{"i":147,"speaker":"たけうち委員","text":"本日、結論を出す、不採択でお願いします。理由は先ほどと同じです。"},{"i":148,"speaker":"安藤委員","text":"本日、結論を出すで、採択なのですけれども、こちらの陳情でも２０人程度にと書いていますので、クラスそのものを２０人ぐらいの規模にするようにしてほしいということだと理解しています。クラスを２０人程度にするというのは、一人ひとりの子どもに行き届く教育環境を実現することになりますし、私はメリットは大きいと思います。コロナなどの感染症対策にもつながると思います。\nこういうのを目指すのだという揺るがぬ目標をしっかりと定めていくこと、その実現のための様々な課題は確かにあります。今すぐやるのは大変かもしれないですけれども、決めない限りは、様々な課題の解消への本気の努力と工夫ですとか、財源措置というのは行われないと思いますので、私は採択を主張したいと思います。"},{"i":149,"speaker":"筒井委員","text":"本日、結論を出すで、不採択でお願いします。理由は、先ほどの請願第１５号と同様の理由です。"},{"i":150,"speaker":"あべ委員","text":"本日、結論を出すということで、不採択でお願いいたします。\n繰り返しになりますけれども、国が３０人学級として打ち出しているということで、先ほども言いましたが、７割の学級というのは既に３０人以下になっているわけですから、それ以上の学級を抱えている自治体が、積極的にこの３０人学級というのをぜひ応援していただきたいと思います。"},{"i":151,"speaker":"横山委員","text":"結論を出すで、不採択でお願いします。先ほどと同様の理由です。"},{"i":152,"speaker":"こんの委員長","text":"それでは、令和２年陳情第５７号につきまして、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":153,"speaker":"こんの委員長","text":"それでは、令和２年陳情第５７号は、結論を出すことに決定いたしました。\n先ほどの質疑で、それぞれの方のご意見を伺いましたので、令和２年陳情第５７号につきましては、挙手により採決を行います。\nそれでは、お諮りいたします。\n令和２年陳情第５７号、すべての子どもが２０人学級で学べる環境をつくるための陳情を採択することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":154,"speaker":"こんの委員長","text":"賛成者少数でございます。\nよって、本件は不採択と決定いたしました。\nそれでは、理事者の入替えにつき、暫時休憩いたします。\n○午後 ２時０９分休憩\n○午後 ２時２０分再開"},{"i":155,"speaker":"こんの委員長","text":"ただいまより、文教委員会を再開いたします。\n────────────────────────────────────────────\n(4) 令和２年陳情第５５号 学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情"},{"i":156,"speaker":"こんの委員長","text":"次に、(4)令和２年陳情第５５号、学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情を議題に供します。\n本件は初めての審査でありますので、書記に朗読をさせます。\n〔書記朗読〕"},{"i":157,"speaker":"こんの委員長","text":"朗読が終わりました。\nそれでは、本件に関しまして、理事者よりご説明願います。"},{"i":158,"speaker":"篠田学務課長","text":"それでは、私からは学校における給食の放射性物質検査についてご説明いたします。\nまず、検査を始めることとなりました経緯でございますけれども、平成２３年に発生しました東日本大震災による福島県の東京電力福島第一原子力発電所の事故がございまして、そこで大量の放射性物質が放出されたということを受けまして、給食の食材に対する影響を懸念する声が寄せられるなどしたことから、保護者の不安を少しでもやわらげるために、給食食材の放射性物質検査を同年秋から実施したものでございます。\n次に、検査体制の推移でございます。当初はヨウ素、セシウムの検査を実施いたしまして、その後発電所周辺の貯留水からストロンチウムが高い濃度で検出されたということから、議会要望等も踏まえまして、平成２６年度からはストロンチウムの測定も追加で行っているというところでございます。それ以降、継続的に検査を実施してまいりましたけれども、その間、放射性物質の検出はない状況が続いていたということでございます。\nこういった状況を踏まえまして、平成２９年度からは、まずストロンチウムの検査でございますけれども、それまですべての学校で年１回実施してきたものを、１年で３分の１の学校での実施に変更しまして、３年間をかけて一通りの学校で実施するという形に変更いたしました。この形にしまして、令和元年度をもちまして一通りの学校での検査は完了したといったところでございますけれども、この時点におきましても放射性物質の検出はなかったということでございますので、ストロンチウムの検査についてはここで一旦休止をするということで対応したものでございます。\nまた、今年度からでございますけれども、これまですべての学校でヨウ素、セシウムの検査をやはり年１回実施をしてきたところでございますが、こちらについても１年で実施する学校数を半分にするということで、２カ年ですべての学校を一通り検査するという体制に変更いたしました。こちらの体制は今年度から変更いたしましたので、来年度をもって一通りの学校の検査ができるといったところで取り組んでいるものでございます。\n最後に、今後の学校給食の放射性物質検査の取組みについてでございますけれども、これまでもその時々の状況を勘案しながら、その実施体制については適宜見直しをしつつ検査に取り組んできたというところでございます。現在実施しているヨウ素、セシウムの検査については、来年度をもって一通りの学校が終わるということでございますので、その先に関してはその調査が完了した時点で、その結果を踏まえつつ、今後について検討していくということを考えているところでございます。"},{"i":159,"speaker":"立木保育課長","text":"それでは私からは、保育園における給食放射性物質検査についてご説明をさせていただきます。\n学校給食と同じく、平成２３年１１月よりヨウ素、セシウムの検査を実施、また平成２６年度からはストロンチウムの検査を実施しておりまして、検査結果はいずれも基準値以下となっております。こうした結果を踏まえまして、保育園においてもストロンチウム検査を令和元年度より休止といたしました。なお、ヨウ素、セシウムの検査は引き続き実施しておりまして、令和２年度からは２カ年で全園を実施することとしております。\nこれまで基準値を超える検査結果はなく、実施体制を見直しながら続けてまいりましたが、来年度、ヨウ素、セシウムの全園検査が完了した時点での結果によるところではありますが、これまで一定の成果があったと認識しておりまして、一旦検査の休止ということを予定しているところでございます。なお、来年度の検査結果や社会情勢の変化があれば直ちに対処できるよう、教育委員会とも連携を取ってまいります。"},{"i":160,"speaker":"こんの委員長","text":"説明が終わりました。\nそれでは、本陳情につきまして、ご質疑、ご意見等がございましたらご発言願います。"},{"i":161,"speaker":"安藤委員","text":"学校のほうは休止ということはまだ出ていないのですけれども、そういう考えは表明されていないのですが、なぜもっと影響を受ける小さな子どもたちが通う保育園のほうは、休止という方針が既に発表されているのか。私は継続すべきだと思うのですけれども、いかがでしょうか。\nそれと、この間の議事録を見ると、経費などもかかっていますみたいなことを言っていますけれども、そういうことを理由に縮小してきているわけですが、多くの自治体が実施してきましたとこの陳情にもありますけれども、他区の検査実施状況などは、品川区としては研究したり参考にしているのでしょうか。つかんでいらっしゃるところがあれば、伺いたいと思います。"},{"i":162,"speaker":"立木保育課長","text":"保育園に関しましてですけれども、決算特別委員会、それから本日も含めまして一応休止という言葉を使わせていただきましたが、今後の検査結果で特段影響がなければ、一旦そこで検査結果の内容をきちんと精査した上で、休止という方法もひとつ考えられる段階ということで、休止という言葉を使わせていただいているところでございます。\nそれから他区の状況ですが、２３区の状況ですと、令和３年度実施予定は、品川区を含めまして１１区ございます。令和２年度も実施は１１区ということで、今のところ把握をしているところです。"},{"i":163,"speaker":"篠田学務課長","text":"他区の実施状況ということで、学校の関係で申し上げますと、令和２年度に関しましては、今の保育課と同じように１１区でございます。これまで、ピーク時では２３区全体のうち２１区で検査を実施してきたところでございますが、今のところ大体半分ぐらいになってきたというような状況でございます。"},{"i":164,"speaker":"安藤委員","text":"保護者の不安を少しでもやわらげるということが目的で始めたというご説明がありましたけれども、やはり具体的に区民の方から継続してほしいという声がこのような形で出るわけですから、これはしっかりと尊重して、ほかの区がどんどん減ってきたということはあるかもしれませんが、ぜひ継続してほしいと思います。\n保育園のほうですけれども、なぜ保育園だけ休止という言葉になってしまったのか。伺ったのは、小さい子どものほうがやはり影響が大きいと思うのです。だから、休止という判断はやめたほうがいいのではないですか、むしろ継続したほうがいいのではないですかという、なぜ保育園のほうはそのように舵を切ろうとしているのかが分からなかったので、伺ったのです。そこがあまり答弁になっていなかったと思うので、聞かせてください。\nそれと今、国が福島のほうで汚染水の海洋放出を早期決定しようとしていることで、地元では大きな反対の声が上がっていますね。反対ですとか慎重な扱いを求める意見書が県議会、あるいは県内５９市町村のうち４１市町村議会で可決をしているという状況もあります。そういう中で、このタイミングで縮小ですとか、そういうのは私は不適切ではないかと思うのですけれども、むしろしっかりと継続・拡充こそ必要なのではないかと思うのですが、いかがでしょうか。"},{"i":165,"speaker":"立木保育課長","text":"保育園のほうだけ休止という言葉を使っているというところでございますけれども、休止という言葉を使っておりますが、区内の子どもたちのことですので、当然教育委員会ともちゃんと連携を取って、今後細かいところは詰めさせていただきたいと思っておりますが、一応これまで一定の成果を出してきたというところがございますので、一旦ここで検査自体は休止の方向で行って、あと後段の質問のところにも関わってくるのですが、今現在区内の食材業者から食材を仕入れているというところで、もう安全なのだということが担保されているところもありますので、保育園のほうとしましては一旦休止を、そしてまた来年度の結果によりますが、もう一旦ここで区切りをつける時期に来たのではないかというところで、休止という言葉を使わせていただきました。ただ、先ほども申し上げましたとおり、きちんと教育委員会とも協議した上で、今後のことは決めていきたいと思っているところでございます。"},{"i":166,"speaker":"篠田学務課長","text":"今この時期に、どちらかといえば拡充ではないかというようなお話でございます。私どもも１０年間にわたって検査を続けてまいりまして、教育委員会のほうでは１件も検出されてきていないという状況がございます。したがいまして、検査自体の意味合いからすれば一定の成果はここで上げられてきているということで、再来年度以降に関しましては来年度の結果を見てということで判断をしていきたいと考えているところでございます。"},{"i":167,"speaker":"安藤委員","text":"１０年にわたってやってきたということですとか、あるいはこれまで一定の成果を出せたのでという話ですけれども、その成果というのはやはり検出がされなかったということが可視化されたということだと思うのです。結果としては検出されませんでしたけれども、それがやはり検査をすることで、しっかりと明らかになったというところが大事なことで、それが安全・安心になるし、不安を取り除くという当初の区の事業の実施目的の達成になるわけですから、私はそういうことが成果だと思います。それをやめてしまうということは、あってはならないのではないかと思います。\n最後、陳情に少し書いていますけれども、一部に検査することそのものが福島の風評被害を生むという議論がありますがということで書いていますけれども、区としては検査するということそのものは、この風評被害を生むとお考えになっているのでしょうか。それも伺いたいと思います。"},{"i":168,"speaker":"篠田学務課長","text":"検査自体での風評被害についてでございます。基本的には給食の食材はすべて国の検査等の体制の中で、安全なものが納入されているという前提で取り組んでいますから、基本的には検査自体が本来は必要がないものだろうという形で捉えているところです。ただ、今回こういった形で、福島県のものということでクローズアップされた中で検査が始まったということですから、どうしても福島県との絡みというのは、これは私どもだけではなくて一般の区民の方から見てもそういう態勢で見ておられるだろうなということからすると、そういう見方をされる方も一定程度はいらっしゃるのではないかと認識しているところでございます。"},{"i":169,"speaker":"安藤委員","text":"一定程度いるかもしれませんということですけれども、品川区はそういう立場に立つべきではないと私は思いますし、むしろ今、先ほど紹介しましたが、政府がもうしようがないから海洋に放出してしまえみたいな、汚染水を流したりとか、そういうとんでもない対応こそが風評被害を生んでいると私は思います。やはりそれを防ぐためには、しっかりと検査を行うということが、そういう事実をもって安全性を確認することになるし、むしろ風評被害を防ぐことになるのではないかと私は思いますので、これはしっかりと継続をしていく必要があると考えております。"},{"i":170,"speaker":"あべ委員","text":"原発事故からもうすぐ１０年が経つわけですけれども、基本的なスタンスとして、私自身は放射能に対する警戒そのものは解いてはいけないと思っております。あの当時のことを考えますと、やはり食材に対して非常に不安に思っていらっしゃる、特に保護者の方が多くて、それに応えるという意味で、様々検査をしてきたということは私はとてもよかったと思いますし、そのことによって安心して給食を利用していただけたということ。それから、どこの産地の食材であっても検査で基準値を超えなかったということは、一定の被災地の農産物に対する信頼とか安心感というのも作ったのではないかと思います。\nそういった意味では、品川区が検査を続けられてきたというのは、私も評価していますし、それからこうした問題に関わってきた保護者の方からも、しばしば品川区はよくやってくれているということで感謝の言葉をいただいているのをこの場でお伝えしておきます。\nただ１０年ほど経って、やはり大分保護者の方々の意識が変わってきたということと、それからそもそもこの検査方式自体が、それほど基準値を上回るような数字が出てくるような検査の仕方ではないという面もあるかと思っております。複数の食材を混ぜて、その中で基準値を超えるなどということだったら、実は相当汚染されている状態だと思われますので、そういう意味ではこの検査方式自体が心理的なものを重視したものだったかなと思います。\nそうした意味では、今後は今の検査方法を続けるというよりはもう少し別の形で、教育委員会あるいは保育サイドとして、給食の安全性というものにアンテナを張っていかれたらよいかと思います。実はさっきも汚染水の話も出てきましたし、また事故から１０年近く経ってきて、放射性物質を収納した容器などが大部劣化して中が出てきているとか、いろいろとやはり経年によって状況が変わってきているのですね。それを、食材を調べることによってその変化をつかむというのは実はかなり厳しいことだと思います。むしろ現地の様子ですとか、あるいはほかの機関で調査をしている農産物、水産物等々の検査結果にアンテナを張るとか、定期的に数字をチェックするとか、そうした形で常にアンテナを張っていただきたいと思います。\nここでこれから検査が縮小あるいは中止ということになっていくと、そうした業務を区内で忘れられてしまっては困るので、ぜひそうしたことは継続してやっていただきたいのです。それをそれぞれ教育委員会なり保育課のきちんとした担当を、別に専門でなくてもそういうことをし続けるという体制だけは残していただきたいと思うのですけれども、いかがでしょうか。"},{"i":171,"speaker":"篠田学務課長","text":"こちらの給食の放射性物質検査については、これまでも学務課の中の給食の担当がおりまして、そこが継続してやってきてございます。給食の担当は別にこの放射能検査だけをやっているわけではなく、通常の給食業務と一緒にやってきたということがございまして、例えば食材の検査だけではなくて、これまでも過去には、例えば牛の干し草から放射能が出たということで、その関係をかなり精査をしながら対応したということもございますので、やはり委員が今ご指摘になったとおり、常日頃から食材に関するアンテナというのは立てた状態で、情報を常に収集しながらきているということもございますので、この体制については引き続き今後も続けていきたいと考えているところでございます。"},{"i":172,"speaker":"立木保育課長","text":"保育課におきましても、保育課に栄養士を置きまして食の安全というところではしっかりとアンテナを張って、今現在も特に放射能だけでなく、そのほかのいろいろな食中毒ですとかいったところにも十分気をつけた中で業務を行っているところです。\n今後も引き続き、正しい知識を子どもたちに伝えるということも大事だと思っていますので、そういったことも含めてしっかりとやっていきたいと思っております。"},{"i":173,"speaker":"あべ委員","text":"どちらも体制としては結構続けていかれるということで安心はしましたが、時間が経っていくと、あるいは検査という目に見えるものがなくなっていくと、どうしてもいつの間にか忘れ去られてしまうということがないように、そこはしっかりとよろしくお願いいたします。"},{"i":174,"speaker":"筒井委員","text":"まず、確認なのですけれども、この放射性物質についての食品検査というものは、東京都と、またさらにその食材の生産地でも検査が行われていて、そして問題がないとされているものが流通しているという理解でよろしいのでしょうか。"},{"i":175,"speaker":"立木保育課長","text":"はい。生産地のほうで、きちんと自治体のほうで出荷にあたりまして検査をした上で流通しておりますので、安全なものが流通していると考えてよろしいかと思います。"},{"i":176,"speaker":"篠田学務課長","text":"食材に対する流通上の問題でございますので、これはあくまでそれぞれの産地の中で間違いのないものが、国の施策の中で流通していると考えているところでございます。"},{"i":177,"speaker":"筒井委員","text":"東京都でも検査されているということでよろしいですか。その点もお伺いしたいのですけれども。"},{"i":178,"speaker":"こんの委員長","text":"筒井委員、今のご答弁で、いわゆるそういうものが、東京都も含めて検査しているものが流通されて、それを使っているのでというご説明と私たちは理解しています。ご答弁はちゃんとされたと思いますけれども。"},{"i":179,"speaker":"筒井委員","text":"生産地はもちろん、生産地と東京都、両方ということですか。"},{"i":180,"speaker":"こんの委員長","text":"そうですね。それで流通されているものを使っているというご答弁ですから。"},{"i":181,"speaker":"筒井委員","text":"わかりました。では、その東京都と食材の生産地で検査されて、問題がないものが流通しているということで理解いたしました。\nそれで、陳情の要旨（２）で、１８歳未満の入所者のあるすべての施設でも検査をお願いしたいということなのですけれども、品川区では今まで学校給食、保育園の給食のみ検査されていたということでよろしいのでしょうか。（２）のように、１８歳未満の入所者のあるすべての施設で検査されていたということはあったのでしょうか。"},{"i":182,"speaker":"篠田学務課長","text":"所管的にどれだけお答えできるか分からないのですけれども、１８歳未満の方々に対して給食を提供する施設というのが品川区内にどれだけあるかということだと思います。私どもも担当ではないものですから、細かいことは把握してございませんけれども、基本的に区の中でそういった施設があったとしても検査をしているといった事例は聞いたことがないので、そういった対応は取っていないのではないかと思います。"},{"i":183,"speaker":"筒井委員","text":"一旦休止というご答弁が再三あったかと思うのですけれども、先ほど福島の処理水放出の件とかがありましたが、当然状況によっては、また再び放射性物質に関する事故とかが起きた場合は、それは柔軟にやはり適宜対応、また再開ということもあり得るという理解でよろしいのでしょうか。"},{"i":184,"speaker":"立木保育課長","text":"一旦検証をした上で中断することになりましても、また必要に応じてそういったものにすぐに対処できるようなことは常に頭に置きながらと考えているところでございます。"},{"i":185,"speaker":"こんの委員長","text":"ほかにございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":186,"speaker":"こんの委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\nそれではまず、令和２年陳情第５５号の取扱いについて、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、自民党からお願いします。"},{"i":187,"speaker":"芹澤副委員長","text":"本日結論を出すで、不採択でお願いします。\n理由としまして、約１０年間検査をしてきて、先ほど一定の成果というお話がありましたが、この成果というのが納入前の検査と品川区の検査に相違がない。納入前の検査に正確性があるというのが保証できたというのが一定の成果なのではないかと思っていますので、今後の流れとして、何か特段の事情で、口に入れる前にもう一度検査をしないと放射性物質等が上がってくるとか、そういったことが出てくればまた実施というのがあるのかなと思っていますが、現状の中では特に拡充をするというような必要性がないと考えています。"},{"i":188,"speaker":"せお委員","text":"本日結論を出すで、不採択でお願いします。\n（１）のほうですが、先ほどからお話がありますように、一旦休止するということがあっても、またアンテナを張っていただいて、あと何かあったら検査していくというお話がありましたので、そこら辺を必ず実施していただければいいかと思います。\n（２）のほうは、コストなども考えて現実的ではないと思いますので、不採択でお願いします。"},{"i":189,"speaker":"たけうち委員","text":"本日結論を出す、不採択でお願いいたします。\n理由としては、ずっと１０年間続けてきて、また来年度まで計画に基づいてやられるということで、ある意味では来年度までは継続なのかと思うのですが、その後も廃止というよりは一旦休止して、状況を見ながら対応していくと。その中には国のいろいろな検査結果等で出てきたりとか、またほかに１１区がやっているということなので、ほかの区の情報なども入ってきた場合とか、いろいろな状況に敏感に対応していただけるものと思っておりますので、そうした面では一旦休止ということではございますが、事業自体は継続していくというようなイメージもあると思っております。\nまた、（２）については実質、なかなかぴったり当てはまるような施設があまり該当しない中で、また拡充ということについては難しいと思っておりますので、不採択ということでお願いいたします。"},{"i":190,"speaker":"安藤委員","text":"本日結論を出すで、採択なのですけれども、やはり検査を縮小する状況にはないと思います。継続こそ必要な状況だと思いますので、採択です。"},{"i":191,"speaker":"筒井委員","text":"本日結論を出すで、不採択でお願いします。\n理由としましては、先ほど冒頭でありましたとおり、東京都と食材の生産地でしっかりと検査されており、それで問題ないものが流通されているということでありまして、品川区も検査していましたけれども、１０年間問題がなかったと。そうした状況で、品川区があえてもう一度二重に検査する必要がないのかなということがあります。\nまた、陳情の（２）番で、そうした状況にあるにもかかわらず、１８歳未満の入所者のあるすべての施設で検査を実施してくださいというのは困難なのかと考えております。\nさらに何か特段の状況に陥れば柔軟に再開ということもあり得るということを伺いましたので、以上の理由で不採択とさせていただきます。"},{"i":192,"speaker":"あべ委員","text":"本日結論を出すということで、不採択でお願いします。\n今後は検査という形ではなくて、情報収集という形でこの問題に引き続きあたっていただきたいと思います。事故現場はまだ安定的な状態とはほど遠い状態ですので、今後また何かが起こってもおかしくないとも感じております。ふだんから情報収集をするとともに、何かあったらすぐにまた検査に戻せるような形でいっていただければ、そういう体制を取っていただければと思います。"},{"i":193,"speaker":"横山委員","text":"結論を出すで、不採択でお願いします。\n検査については、これまでの経過と今後の検査結果や情勢の変化、また他自治体の状況ですとか運用のリソースに関する課題など、引き続き子どもたちの安全確保のために総合的に対応をしていっていただきたいと考えています。"},{"i":194,"speaker":"こんの委員長","text":"それでは、まず令和２年陳情第５５号につきましては結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":195,"speaker":"こんの委員長","text":"それでは、令和２年陳情第５５号は結論を出すことに決定いたしました。\n先ほどの質疑でそれぞれの方のご意見を伺いましたので、令和２年陳情第５５号につきましては挙手により採決を行います。\nお諮りいたします。\n令和２年陳情第５５号、学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情を採択することに賛成の方は挙手願います。\n〔賛成者挙手〕"},{"i":196,"speaker":"こんの委員長","text":"賛成者少数でございます。\nよって、本件は不採択と決定いたしました。\n────────────────────────────────────────────\n１ 議案審査\n(6) 第６３号議案 令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）"},{"i":197,"speaker":"こんの委員長","text":"次に、予定表１、議案審査に戻りまして、(6)第６３号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":198,"speaker":"廣田子ども育成課長","text":"私からは、歳出の子ども未来部所管分についてご説明申し上げます。補正予算書１６ページをご覧ください。\n第３款民生費、２項児童福祉費、３目子育て応援費につきましては、２７５万３,０００円を追加し、９７億８,４９５万７,０００円とするものでございます。内容は後ほど説明させていただきます。\nおめくりいただきまして、１８ページになります。４目児童保育費を２８万２,０００円追加し、１４５億８,６５６万８,０００円といたします。５目保育支援費につきましては７６万６,０００円を追加し、２５３億８７６万８,０００円とするものでございます。\n４目、５目、これらにつきましては、いずれも指定寄附金等を含めまして使わせていただきまして、各種保育施設、幼稚園等における感染拡大防止対策の物品を購入するものでございます。この後、子育て応援課長より、補足説明がございます。"},{"i":199,"speaker":"三ッ橋子育て応援課長","text":"子ども食堂への運営費補助について説明いたします。資料をご覧ください。\n１、事業目的でございます。地域の子どもやその保護者が気軽に立ち寄り、相互に交流を行う場を提供する子ども食堂の活動に加え、新型コロナウイルス感染症に伴い、在宅の子どもやその保護者を対象にお弁当や食材などの食事を提供する子ども食堂を支援することを目的といたします。\n２、事業内容でございます。（１）対象者は区内子ども食堂であり、申請は６か所でございます。\n（２）補助対象経費は、食事の提供、感染症防止対策・食中毒防止対策等に必要な経費でございます。\n３、補正予算額は２７５万３,０００円であり、東京都の補助率１０分の１０でございます。"},{"i":200,"speaker":"有馬庶務課長","text":"それでは私から、教育委員会分、第７款教育費についてご説明いたします。予算書の２０ページをご覧ください。\n１項教育総務費、１目教育推進費を３５１万２,０００円追加し、５４億３,１４９万１,０００円とするものです。これによりまして、教育費の計は予算書７ページのとおり、２９４億３,６８０万７,０００円とするものでございます。\n内容は修学旅行のキャンセル料等で、新型コロナウイルス感染症の影響を受け、学校としてやむを得ず中止や時期を変更したケースが生じており、この場合に発生する費用を公費負担することで保護者への経済的負担軽減を図るための経費として、前回の補正に引き続き計上したものでございます。\nなお、「キャンセル料等」と「等」を付したのは、日程を変更する場合、旅行事業者によって変更移行料という名目の経費がかかることから、その経費も含めて計上したものでございます。補正の内訳としては、キャンセル料が５校、変更移行料が１校の計６校分の実績分でございます。"},{"i":201,"speaker":"こんの委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":202,"speaker":"安藤委員","text":"まず、子ども食堂の運営費補助ですけれども、今回手が挙がったのは６施設ということですが、全食堂から希望を伺ったと伺いましたけれども、その中で子ども食堂運営主体者の現状とか要望ですとか悩みですとか、区として、もしつかんだことがあれば教えていただきたいと思います。\nそれと保育園の感染症対策ですけれども、これはクラウドファンディングによるコロナ対策寄附が全体で７１９万円で、保育園部門には６８万円の充当ということだと思うのですが、自助・共助というのは否定しませんけれども、それぞれが皆さん自分でも努力していますし、困難な状況にも直面している中、やはり共助ではなかなか限界があるのかなと、お気持ちという感じにならざるを得ないような内容だと思うのです。やはり不要不急な事業は大胆に見直すなど、大局を見て財政出動とか公助というのはやはり大事なのではないかと。今回はそういうお気持ちを届ける、残るものを送るというやり方にとどまらざるを得ませんでしたけれども、今保育の現場からは、コロナ禍に直面してどういうご支援の要望が出ているのか、お伺いしたいと思います。\n最後、３点目は修学旅行のほうですけれども、義務教育学校の後期課程も含めて中学校１５校の中で、既に修学旅行が実施できたところ、延期して実施を予定しているところ、残念ながら中止になってしまったところ、それぞれ何校ずつになっているのかを伺いたいと思います。"},{"i":203,"speaker":"三ッ橋子育て応援課長","text":"子ども食堂の現状や要望、または悩みなどでございますけれども、子ども食堂ネットワーク事務局、社協を通じて様々ご意見はいただいております。例えば今、コロナ禍においてフードパントリーを実施するにあたっても、確かに消毒など非常に気をつけながら実施しているということ、それは今までと生活様式が変わっていくことに対する悩みもあるようです。また、やむを得ず中止している子ども食堂もございまして、やはりこれから開催するとしたらどうやっていけばいいのか、開催しているところに聞いたりというような悩みがあるようです。"},{"i":204,"speaker":"吉田保育施設調整担当課長","text":"保育園におけるコロナ対策の支援ですけれども、今までマスクやアルコール、そのほかのものを配布してきたところでございます。また引き続き現場と確認しながら、必要なものは充足させるとともに、また心の支援等のバックアップを行っていければと思っております。"},{"i":205,"speaker":"若生保育支援課長","text":"私立幼稚園、保育園等に関しましても、やはり感染の今後の動向を見据えると、マスクですとか消毒液というところは、今後も引き続き必要になってくるだろうということは認識してございます。各園からの聞き取り等の情報で言いますと、現在はある程度マスクですとか消毒液の調達はしやすい状況にはなっています。ただその一方で、どうやって園内の感染を防いでいくかというところの情報提供、どういったやり方があるかというところでは、区立園ではどうなっているかとかいったことをいろいろと教えてほしいというご要望をいただいたときに適宜情報提供しつつ、あと、前回の補正でメンタルヘルスの相談窓口の設置等も行いますので、そういったところでまたサポートしていきたいと考えております。"},{"i":206,"speaker":"有馬庶務課長","text":"修学旅行の状況でございますが、中学校、義務教育学校後期課程全１５校のうち、実施済みの学校は２校でございます。残念ながら中止とした学校は７校でございます。残りの６校につきましては、一応３月ということで予定をしているものでございます。"},{"i":207,"speaker":"安藤委員","text":"修学旅行ですけれども、文化祭など様々な行事が中止になっていることで、ある先生が生徒から言われたという話を聞いたのですが、疲れる練習もないしわずらわしい人間関係もないけれども、私たちには感動もないと。あるのは勉強とテストだけなのだといわれてしまったそうなのです。\n修学旅行が本当に残念ながら中止になってしまったところは、やはり本当にそのときでしか味わえないものですから、本当に何とかしたいと思うのですけれども、コロナの問題があるので単純ではないと思うのですが、形にはまらず、また上から何か思い出はこうだと決まったものをおろすというのではなくて、やはり何らかの思い出づくりの機会というのを生徒同士で話し合って考えて作っていくということがあってもいいのではないかと思うのです。\n区の教育委員会としても、そういう学校での工夫を後押しするような柔軟な環境ですとか、あるいはそういうのを現場に提供してあげてほしいという思いがあるのですけれども、そこら辺はいかがでしょうか。"},{"i":208,"speaker":"矢部教育総合支援センター長","text":"修学旅行が未実施だった学校については、どこかで判断しなければいけませんので一応中止にしていますが、今でも代替案を考えるという学校もございますし、これまでも基本的には実施するという方向でこちらも促してまいりました。ただ安全第一ということでございますので、そこは学校が子どもたちや保護者の考えを聞きながら決めていくところと認識しております。"},{"i":209,"speaker":"有馬庶務課長","text":"生徒が工夫しながら何か考えてということ、それはそれぞれの学校がそれぞれ考えて、思い出づくりに取り組んでいるということもございますし、このたびの決算特別委員会でのご意見を受け、教育委員会が背中を押して、何かを提案して示したほうがいいのではないかというようなことで、今、教育委員会としても思い出づくりとして、このようなことができるのではないかということを提案して学校に投げているところで、両面から、その卒業生に対して支援をしているところでございます。"},{"i":210,"speaker":"安藤委員","text":"中止になってしまったところについては、代替案を考えているところもあるということですが、ぜひそういう営みというのを全面的にバックアップしてあげてほしいということは改めて要望したいと思います。\n最後、中止になってしまったところ７校というのは、やはりもう大体中止になって終わりというのではなくて、ほとんどはそういう代替的なものを何か実施される予定になっているのかというのが１つと、それと３月に延期になったところが、仮に感染状況などでどうしても、ぎりぎりなのですけれどもそこで中止になってしまったという場合は、やはり今回のように少なくともキャンセル代等は出してあげるというのは行うべきだと思うのですが、そちらについてはいかがでしょうか。"},{"i":211,"speaker":"矢部教育総合支援センター長","text":"１点目についてお答えしたいと思います。７校中、数はまだ十分把握できてございませんが、代替を考えているということで、こちらとしては日帰りとか近い距離でということでご案内をしております。"},{"i":212,"speaker":"有馬庶務課長","text":"今後予定している学校、３月に無事に行けたらぜひ行っていただきたいと思いますけれども、感染状況で万が一そういうことになれば、ほかの学校と同様、キャンセル代等については公費負担をしていきたいと考えております。"},{"i":213,"speaker":"たけうち委員","text":"子ども食堂ですが、ここに６施設ということなのですが、そうするとほかの施設については、今こういうコロナ禍の中で子どもたちが来ることを心配して、今、本来の子ども食堂の活動も休止してしまっていて、それで致し方なくお弁当とかそういう部分でこの６施設が手を挙げたという理解なのか、今通常の子ども食堂の活動はもう再開されているのか、その辺の状況が分かれば教えていただきたいのが１つです。\nあと、保育園の寄附金のところですが、これまでも現金等を保育園の保育士のほうに寄附という形でやってきましたけれども、今回もこれは寄附金という形で、金額の大小から言えば決してそれほど大きなものではないのかもしれませんが、やはり区民からそういう保育に携わっているいわゆるエッセンシャル・ワーカーの一つの分野でもあるそういう方たちに対して、そういう声、真心が届いているということが大事なのかと思いますので、そういう趣旨で届いたものをこういう形でお届けしますということで、ぜひそれは強調していただきたい、そこが大事だと。もちろん自助・共助・公助といろいろとある中でのお考えもあるでしょうけれども、やはりそういう真心が大事だということをぜひ申し伝えてもらいたいと思うのですが、それについて、よろしくお願いします。"},{"i":214,"speaker":"三ッ橋子育て応援課長","text":"子ども食堂は現在区内に２４カ所ございまして、その中でフードパントリーを実施しているところが１２カ所ございます。また通常開催が５カ所ございます。その中で、コロナで中止をしているところが一方で４カ所ございます。こちらで６カ所今回申請していただいたところは、すべてフードパントリーを実施しているところ、また通常開催されているところもございます。"},{"i":215,"speaker":"若生保育支援課長","text":"保育園等に対するクラウドファンディング等で寄附いただいたものを活用させていただいてというところで、今回基本的に金額等もそこまで大きくないというところもございまして、物品等で工夫をさせていただく形を取るということで、そこに関してはありがたい区民の皆様からの寄附という形の感謝と激励の声を、保育に従事している皆様にお届けするという趣旨がきちんと伝わるように、例えば物品のほうにメッセージカードですとかシールで寄附で贈られたものというのが分かるような形で表示させていただいて、お届けするということを考えているところでございます。"},{"i":216,"speaker":"あべ委員","text":"子ども食堂の運営費補助についてなのですけれども、これは補正額２７５万円で、対象、申請があったところが６カ所ということは、１カ所四、五十万円平均ぐらいになるのですけれども、これはどういう形で金額を決めたのかというところと、今稼働しているところが、分かっているだけで１５カ所あるわけですね。申請しなかったところは何でしなかったのでしょうか。なぜ６カ所だけの申請になったのかは把握されているのでしょうか。"},{"i":217,"speaker":"三ッ橋子育て応援課長","text":"今回、子ども食堂につきまして、６カ所の中で、この補助金と申しますのは、新型コロナウイルスにおきまして影響を受けている、そしてその中でフードパントリー等を実施しているところであったり、内容が東京都の内容に基づいて対応しているところでございます。\n実際には東京都の緊急対応について子ども食堂の現状を、子ども食堂ネットワーク事務局を通じて把握したところでございます。その中で、コロナ禍における運営支援が必要な食堂がこの６カ所、申請があったということが一番大きいところでございます。\nなぜほかのところ、例えばフードパントリーは１２カ所ありますけれども、それ以外の６カ所というのは、この補助金をいただかなくても実際にできるという判断をその子ども食堂がしたのであろうと思われます。実際には１カ所あたり、この補助金は１７０万円まで補助の申請ができることになりますので、それをすべての子ども食堂に対して周知しております。その中で、申請をしようと思ったところが６カ所だったということでございます。"},{"i":218,"speaker":"あべ委員","text":"すみません。東京都のこれを先に見てから問えばよかったのですけれども、こういう補助制度があって、完全に中止しているのであればともかく、実施するにはやはり何らかの対策を皆さん取っていらっしゃると思うのです。その中で少なくとも１５カ所がやっていて、６カ所しか出てこなかったということは、このお金がなくてもいいよという判断だったというのは、むしろ例えば補助要件が厳しすぎたとか、あるいは書類の書き方がよく分からないとか、情報が行っていないとか、締切りが早かったとか、何だかむしろそういうところに申請しない原因が通常あるかと思われるのです。お金が要らないというだけのことではないのではないかと思うのですけれども、そこら辺はもう少し突っ込んでいないのですか。ある程度の規模のところではないと駄目とか、申請したいけれども、この条件があるからできなかったところがあるとか、そういうことは把握されていますか。"},{"i":219,"speaker":"三ッ橋子育て応援課長","text":"こちらの申請の内容でございますが、詳しく申し上げますと、食事の提供に必要な経費、これは賃借料、会場使用料、食材費、光熱水費、保険料、配送料に加え、ワゴン車のリースやクーラーボックス、マスク、消毒液の購入等、また配食、宅食および食中毒防止対策、感染症防止対策等に必要な経費。こちらは人件費は対象外となっておりますけれども、これだけ非常に広い門を開いているところでございます。\nそれでも申請をしてこなかったというのが現状でございまして、こちらとしても、申込みをされていないほかの子ども食堂にもきちんとネットワーク事務局を通じて何回か確認しております。しかしながら申請してこなかったということで、特に書類も難しいものではないですし、内容につきましても十分ほかの補助金をもらっているところもあると思われますので、これを使わなくても対応できているのだと思っております。"},{"i":220,"speaker":"あべ委員","text":"今のお話を伺っていると、結構広範に補助が出るにもかかわらず、休止中もありますけれども、２４カ所あるうちの実際に稼働しているのが１５カ所で、申請６件というのはどうも腑に落ちないのです。ネットワーク事務局で直接はされているということなので、これは私のほうでも少し現場に聞いてみたいと思いますけれども、仮定の話で申し訳ないのですが、これは東京都の補助金で、これを申請されなくても、実はこういう理由で申請しなかったけれども、実はこういうのが運営では必要なのだという声が挙がってきたら、それは区としてはある程度対応を考えるということはあり得るのでしょうか。"},{"i":221,"speaker":"三ッ橋子育て応援課長","text":"まず今回、申請は一旦締め切らせていただいているところですけれども、実際に第３回の募集が東京都であるのかどうかは確認しますが、今回にあたりましてはもう募集期間を終わっていると認識しておりますので、申請をされていないところに対しては、申し訳ないのですけれども無理なのではないかと思っております。"},{"i":222,"speaker":"横山委員","text":"こちらの感染拡大防止対策物品購入の部分になるのですけれども、こちらは現場の実情に即したサポートですとか、感染拡大防止物品を購入する際に現場にとって必要なものをより柔軟に選択できるなど、可能な限り園長先生ですとかまたは校長先生の判断で、迅速かつ柔軟に使い勝手のよい支援をお願いしたいということをまずお伝えさせていただきます。\nそして補助の内容についてなのですけれども、これまで現場のほうからどのような意見がありますでしょうか。実はこういうものが欲しいけれども、補助の中ではちょっと買えないので困っているということがあるのではないかということを懸念しているのですが、そのあたり、現状をお聞かせください。"},{"i":223,"speaker":"若生保育支援課長","text":"感染対策物品の購入については、ご指摘のとおり、特に私立の保育園・幼稚園ですと、園によって様々ニーズが異なるということで、こちらが一方的に特定したものをお送りするとなかなかニーズに合わないことになろうかというところで、今回、幾つかの商品を消耗品ではないような形で、例えば自動で消毒液を出すような消毒器といったものですとか、あるいは様々複数のものを選べるような形で補填しようと思っているところです。\nその中で園のニーズですけれども、先ほどの答弁と繰り返しになりますが、消耗品はかなりもう充足されている部分がありまして、これが特に欲しいというようなお声は今のところ最近では届いていないところで、どちらかというとソフト面の対策等を求める声が大きいようであります。そういったお声も伺いながら、今後も感染防止対策に総合的に対応してまいりたいと思っております。"},{"i":224,"speaker":"横山委員","text":"そういった様々な現場との意見交換ですとか要望を吸い上げていただいているということで、安心をいたしましたけれども、またそうした現場の情報、ニーズですとか意見といったところを、例えば国や都などにそうした意見・要望をスピーディーに情報共有するなどの働きかけもお願いしたいと思うのですが、そうした情報共有の現状についてもお聞かせいただけないでしょうか。"},{"i":225,"speaker":"若生保育支援課長","text":"国ですとか東京都との情報共有の場ということで、私立保育園等の関係ですと、２３区の課長会ですとか待機児童対策の協議会等もございますので、そういったところで国とか東京都のほうに各種要望を上げているところでございまして、そういった中で各区とも情報共有なども行っているところです。今後ともそういったところを活用しながら、適切に要望を上げていきたいと考えております。"},{"i":226,"speaker":"筒井委員","text":"この感染拡大防止対策物品購入費についてなのですけれども、保育園とか幼稚園のもので、これは物品の対象を限定しているとかはあるのでしょうか。こういう品物でないといけないとか、それを確認したいのですけれども。"},{"i":227,"speaker":"若生保育支援課長","text":"今のところ一つに限定をしているのではなく、幅広く選べるような形で複数の物品をこちらのほうで選定して、それでご希望に応じて選んでいただくという形を想定しているのですけれども、何にするかという特定に関しては、園ごとで個々に聞き取ってというのは現実的に難しい部分でございますので、そこはある程度金額と見合ったものを私どものほうで選定させていただいた上でご提示するという方法で考えてございます。"},{"i":228,"speaker":"筒井委員","text":"ある程度ご提案されるということなのですけれども、これから寒い時期になってきまして、乾燥というのもある程度防がなくてはいけませんし、また換気もかなり有効にやっていかなければいけないということもあるので、こういった季節、これからの寒い冬の時期に対応した物品の選定、提案というのもぜひ行っていただきたいと思っておりますが、そのあたりはどのようにお考えでしょうか。"},{"i":229,"speaker":"若生保育支援課長","text":"そういったご意見等々も園のほうにお伺いしながら、今のところこちらで想定しているものはあるのですけれども、ご案内いただいたようなご要望がございましたら、柔軟に対応してまいりたいと考えています。"},{"i":230,"speaker":"せお委員","text":"１点だけ、先ほどの子ども食堂のあべ委員の質疑の中で申請が６カ所というのがあって、私もちょっと少ないかなと思ったのですけれども、申請が終わってしまったということで、今後に活かすためにアンケートを取ったりとか、お声を聞いたりとか、そういうことをしたりする予定はないのでしょうか。"},{"i":231,"speaker":"三ッ橋子育て応援課長","text":"今回の子ども食堂のこの補助金に関して、期間を長くて取って、なおかつネットワーク事務局とも何回もやり取りをしておりまして、各子ども食堂も十分理解した上での申請と捉えておりますので、また改めてアンケートを取ることは今のところ考えていません。"},{"i":232,"speaker":"芹澤副委員長","text":"１点だけ、今のところの確認で、確かに少ないかなと。１０分の１０なので少ないと思うのですが、これは私もぱっとしか見ていないのですけれども、同趣旨の補助を受けている場合は申請できないみたいなことが書いてあったように思っていて、子ども食堂というのは飲食店の経営されている場所でやっていたりとかいうのがよくあると思うのですが、例えばそこの飲食店のほうで販路拡大なり何なりいろいろな感染症対策の補助金を例えば申請されている場合、そもそもこの補助金が申請できないとかいうことは、条件としてあるのでしょうか。"},{"i":233,"speaker":"三ッ橋子育て応援課長","text":"こちらは東京都の申請書でございますけれども、特にその子ども食堂が飲食店を経営していて、そこが補助金をもらっているからといってということは、文言については改めて言及していないところでございます。したがいまして、例えば飲食店が子ども食堂をしているところも、申請しているところは実際にございますので、それは大丈夫でございます。"},{"i":234,"speaker":"こんの委員長","text":"ほかにございませんでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":235,"speaker":"こんの委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、本件につきまして各会派の態度を確認します。\nそれでは、自民党からお願いします。"},{"i":236,"speaker":"芹澤副委員長","text":"自民党は賛成します。"},{"i":237,"speaker":"せお委員","text":"賛成です。"},{"i":238,"speaker":"たけうち委員","text":"賛成です。"},{"i":239,"speaker":"安藤委員","text":"賛成です。\n第３波も到来して、今のコロナ禍の厳しい状況に見合った規模や内容という点ではちょっと不十分かなと思いますけれども、内容がいい内容なので、賛成です。"},{"i":240,"speaker":"筒井委員","text":"賛成です。"},{"i":241,"speaker":"あべ委員","text":"賛成です。"},{"i":242,"speaker":"横山委員","text":"賛成です。"},{"i":243,"speaker":"こんの委員長","text":"それでは、これより第６３号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）について、採決をいたします。\nお諮りいたします。\n本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":244,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n３ その他\n(1) 所管質問について"},{"i":245,"speaker":"こんの委員長","text":"次に、会議の運営上予定表の順番を入れ替えまして、予定表３のその他の(1)所管質問についてを議題に供します。\n所管質問に関しましては、会議の効率的運用の観点から、なるべくご配慮をいただきたいと思っております。その上でなお、ご発言を希望される方はお申し出いただきたいと思いますが、いかがでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":246,"speaker":"こんの委員長","text":"ありがとうございます。それでは、その他は一旦これまでといたします。\nそれでは、理事者の入替えにつき、暫時休憩いたします。\n○午後 ３時２９分休憩\n○午後 ３時４０分再開"},{"i":247,"speaker":"こんの委員長","text":"ただいまより文教委員会を再開いたします。\n────────────────────────────────────────────\n１ 議案審査\n(1) 第６６号議案 品川区立保育所条例の一部を改正する条例について"},{"i":248,"speaker":"こんの委員長","text":"次に、予定表１の議案審査に再び戻りまして、(1)第６６号議案、品川区立保育所条例の一部を改正する条例についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":249,"speaker":"吉田保育施設調整担当課長","text":"それでは私から、第６６号議案、品川区立保育所条例の一部を改正する条例についてご説明いたします。資料をご覧ください。\nまず、１の改正理由でございますが、建替えに伴う移転による所在地の変更等について改正するものでございます。\n次に、２の改正内容です。（１）三ツ木保育園ですが、現在の老朽化した施設の大規模改修を実施するため、戸越公園の一部に仮設園舎を建設し、約２年半移転いたします。所在地は西品川一丁目９番１８号から豊町二丁目１番３０号へ変更となります。条例の施行期日は令和３年４月１日です。なお、大規模改修工事後、令和５年４月に移転前の場所に戻ります。\n（２）南ゆたか保育園ですが、現在の老朽化した施設の大規模改修工事を実施しており、その間旧荏原第四中学校跡地のほうに移転しておりますが、改修工事終了後は移転前の場所に戻ります。所在地は豊町三丁目５番３１号から豊町四丁目１７番２１号に変更となります。施行期日は令和３年４月１日です。\nそれでは、裏面になります。（３）八潮西保育園ですが、現在老朽化した施設の大規模改修を実施しており、その間、八潮南保育園の跡地に移転しておりますが、改修工事後は移転前の場所に戻ります。所在地は、八潮五丁目８番４１号から八潮五丁目４番１６号に変更となります。施行期日は令和３年４月１日です。\n（４）ひろまち保育園ですが、閉園に伴い削除いたします。施行期日は令和３年４月１日となります。\n３の新旧対照表は別紙のとおりでございます。"},{"i":250,"speaker":"こんの委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":251,"speaker":"安藤委員","text":"三ツ木保育園と八潮西保育園は民営化対象園ですけれども、なぜ民営化の直前に建替えや大規模改修行うのか、民営化との関係は何なのでしょうか、伺います。\nそれと、ひろまち保育園のほうですけれども、６月の当委員会で報告がありました在園児３１名の優先転園の結果はどうなったのか。分かれば地区ごとの、何地区に転園みたいなことで内訳などが分かれば伺いたいと思いますし、あと、現在のひろまち保育園は開設当初は委託事業者の変更など混乱があったと思うのですけれども、現在の園の運営について、現時点で区はどのように評価していらっしゃるのか。また、子どもや保護者の評価はどのように聞いていらっしゃるでしょうか。伺いたいと思います。"},{"i":252,"speaker":"吉田保育施設調整担当課長","text":"３点のご質問をいただいたかと思います。\n民営化の前に三ツ木保育園と八潮西保育園を改修するのはなぜかというところですけれども、もともとこの建物自体が老朽化してまいりました。あと民営化を進める上で、建替えをした後、よい状況で事業者を募集したほうが、よりよい運営事業者を得られると考えまして、まずは民営化の前に工事を行っているところでございます。\nそれから、ひろまち保育園の在園児の優先転園結果がどうなったかというところでございますけれども、現在すべての園児につきましては、それぞれが申請の際に希望していただいた園の中のどちらかに優先転園されている次第でございます。現在のところ、優先転園ができなかったという方はおりません。\nそれから、ひろまち保育園の現在の運営状況についてというところですけれども、事業者変更後は特に問題もなく進んでまいりまして、現在は閉園に向けた準備を進めているところでございます。"},{"i":253,"speaker":"安藤委員","text":"定員が多いひろまち保育園が縮小、なくなることで、周辺地域、あるいはここは最も厳しい１歳児園ですので、１歳児の入園ですとか、あるいは２歳児までしかいられない認証保育園の在園者などに、やはり厳しい影響が出ることになると思うのですけれども、いかがでしょうか。また、それをカバーする方策というのは区は持っていらっしゃるのでしょうか、伺いたいと思います。"},{"i":254,"speaker":"立木保育課長","text":"入園の関係になりますので、私のほうからお答えさせていただきます。\n現ひろまち保育園で、今回３１名の方が優先転園の対象になりまして、２８名の方が転園をご希望されました。そのほかご希望されなかった方が３名いらっしゃるのですが、そういったご希望された方の転園先のほうは、すみません、どちらにということは今手元にないので個別には申し上げられないのですが、今回の優先転園による来年４月の入園枠への影響というのは、今のところ最小限に抑えられているというところで、大井町周辺にも新規開設園もございます中では、特に影響を出さずにここは優先転園が実施できたと捉えているところでございます。"},{"i":255,"speaker":"安藤委員","text":"やはり私は、転園希望の方もそうですけれども、そもそもこの１歳児園の大きな枠が、廃園になってしまうとごっそりなくなってしまうということで、やはり来年３月で閉園するということで様々な影響があると思うのです。３１名の方が転園を余儀なくされる、あるいは３名の方は希望しないということは、これを機会に保育園を退園してしまうということだと思うのですけれども、せめて今いる在園児が最後まで、この園で卒園するまで存続するべきだと、保育部門として思わないのかなと私は思うのですが、それができない理由を具体的に改めて伺いたいと思います。"},{"i":256,"speaker":"吉田保育施設調整担当課長","text":"ひろまち保育園につきましては、開園当初より５年間の期間限定園ということで進めてまいりました。そのため、平成２８年から数えまして５年間になります今年度をもって、閉園することにした次第でございます。"},{"i":257,"speaker":"安藤委員","text":"私が伺ったのはこれができない理由で、別に今のはできない理由にならないと思うのです。約束していましたという、約束したかもしれませんが、約束したにしてもしていないという話もありますし、不十分という話もありますし、仮に百歩譲ってそうだったとしても、それはやはりできない理由にはならないと思うのですけれども、もう一回お伺いします。"},{"i":258,"speaker":"吉田保育施設調整担当課長","text":"大井町周辺の開発の関係もございますけれども、都市計画部門とともにＪＲと調整した結果、来年度以降、現在のひろまち保育園がある場所を使うことが難しいところもありましたので、今年度予定どおりの閉園ということにさせていただいてございます。"},{"i":259,"speaker":"あべ委員","text":"まず保育園の移転のほうなのですけれども、三ツ木保育園は前も出ていたかもしれませんが、どのくらい距離があるのでしたっけ。まずはそこの確認をお願いします。"},{"i":260,"speaker":"吉田保育施設調整担当課長","text":"三ツ木保育園と新しく移転する先の間の距離ということかと思います。約１km程度と考えております。"},{"i":261,"speaker":"あべ委員","text":"保育園の建替え、それに伴う移転というのは、用地の確保が難しいというのは非常によく分かるのですけれども、やはり在園されている子どもや特に親御さんにとって負担が大きいものだと思っております。\nそれで、やはり優先転園みたいな声も一部には挙がっていたかと思うのですけれども、今のところは移転に伴う転園で何らかの配慮をするということは、品川区はやっていなかったと思うのです。ただ、これは今後考えてもいいのではないかと。転園ですから、全体のキャパシティから言えばプラス１、マイナス１なので、保育行政としては大きな負担にはなるわけではなく、かつお子さんの年齢や兄弟の状況などによっては、やはり一定の距離以上のところというのは、むしろ転園を認めるということも、優先転園の仕組みを作るということも一つの考え方ではないかと思うのですが、これまでやっていなかったのは承知していますけれども、今後の可能性として検討されるのも一つの合理的なやり方ではないかと私は思いますが、いかがでしょうか。"},{"i":262,"speaker":"立木保育課長","text":"こちらの優先転園に関しましては、やはりいろいろと諸条件がございます。そうした中で適用できたのがひろまち保育園、それからほうさん保育園ということになるのですけれども、それ以外、こういった例えば改築にあたって、通常１kmですと、ある程度通える範囲というところで、私どもも極力そういった場所が出たときに改築を進めるということになっておりますので、そうした中でそれを認めますと、ちょっとほかの方との関係も出てきますので、なかなか一定難しいと考えておりますが、ちょっとこれはほかの制度、国、都の状況を見ながら、今後もしそういうことが増えてくるようであれば、そういうのは検討しなくてはいけないとは思っています。"},{"i":263,"speaker":"あべ委員","text":"すぐに結論が出る問題ではないかもしれませんけれども、やはりもともとの園のすぐ近くであれば１kmなんですが、既に遠くてさらに１kmとなると、かなり毎日のということを考えると負担にもなってくるかと思います。ぜひご検討をいただければと思います。要望にしておきます。\nそれともう一点、ひろまち保育園ですが、こちらの事業者は今年度以降どうなるのかということも教えてください。"},{"i":264,"speaker":"吉田保育施設調整担当課長","text":"現在はＨＩＴＯＷＡキッズライフという会社が委託を請け負っております。契約のときから、閉園した際に、自社で本人の希望を聞きながら別の園だとか、そういうところに移れるようなことができるようにということをお願いしているところがありますので、閉園した際はそのような対応を取るものと考えております。"},{"i":265,"speaker":"あべ委員","text":"こちらのひろまち保育園の現スタッフですけれども、先ほども特に問題はなくというような表現をされておりましたが、保育の質がいろいろと問題になっている昨今の中で、現在のひろまち保育園というのは相対的に見てかなりレベルの高い保育をされていると私は受け止めております。多分関係者の中でも、園の毎年の保育展などに足を運ばれているだろうと思っているのですけれども、あれだけの保育をされている保育園というのは品川区内の中でもやはり上位に入るのではないかと思っております。\nしかもあの園は、品川区立の保育園の職員だった方も少なからずいるということで、となると品川区のこれまでの保育の蓄積というのが、今、事実上ひろまち保育園の中にかなり残っているというのは非常にありがたいことであって、単に契約が終わっても事業者がどこかで雇ってくれるよということではちょっともったいない。むしろ、今後の品川区の保育に積極的に活かしていっていただくほうが、区の保育のためではないかと思うのですけれども、そうした視点はお持ちでしょうか。"},{"i":266,"speaker":"吉田保育施設調整担当課長","text":"閉園したところを運営している民間事業者の職員が、その後どうするかというところは、なかなか区でコントロールしづらいところだと思います。確かにおっしゃるとおり、ひろまち保育園を作るときに、元品川区の職員が何人か勤めているというところもございます。今後、その辺がどうなるかは難しいところもございますが、考えてまいりたいとは思っております。"},{"i":267,"speaker":"こんの委員長","text":"ほかにございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":268,"speaker":"こんの委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、本件につきまして各会派の態度を確認します。\nそれでは、自民党からお願いします。"},{"i":269,"speaker":"芹澤副委員長","text":"賛成します。"},{"i":270,"speaker":"せお委員","text":"賛成です。"},{"i":271,"speaker":"たけうち委員","text":"賛成です。"},{"i":272,"speaker":"安藤委員","text":"態度は反対なのですけれども、老朽化した区立園の建替えの必要性は理解するところなのですけれども、南ゆたか保育園について行政上の目的であり、異論はありません。しかし三ツ木保育園、八潮西保育園の所在地変更については、やはりやるべきでない民営化を前提にして、改築してきれいな保育園を民間に渡していくための住所変更だということで、賛成できないと。あと、ひろまち保育園についても、やはり再開発を優先することによる閉園で、子どもたちの育ちにもよくない影響を与えますし、待機児童解消にも逆行すると思いますので、反対なので、条例全体としてこれには反対という態度になります。"},{"i":273,"speaker":"筒井委員","text":"賛成です。"},{"i":274,"speaker":"あべ委員","text":"賛成です。"},{"i":275,"speaker":"横山委員","text":"賛成です。"},{"i":276,"speaker":"こんの委員長","text":"それでは、これより第６６号議案、品川区立保育所条例の一部を改正する条例についてを採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することにご賛成の方は挙手願います。\n（賛成者挙手）"},{"i":277,"speaker":"こんの委員長","text":"賛成多数でございます。\nよって、本案は原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(2) 第７５号議案 指定管理者の指定について"},{"i":278,"speaker":"こんの委員長","text":"次に、(2)第７５号議案、指定管理者の指定についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":279,"speaker":"三ッ橋子育て応援課長","text":"指定管理者の指定について、説明いたします。資料をご覧ください。\n１、管理を行わせる施設は、品川区立家庭あんしんセンターであり、２、指定管理者候補者は、社会福祉法人福栄会でございます。\n３、指定期間は令和３年４月１日から令和８年３月３１日でございます。\n４、候補者の選定は、「品川区指定管理者制度活用に係る指針」に基づき、運営者に連続性が要求されることから、公募によらず特定の事業者を指定管理者候補者として選定を行うこととし、選定委員会に付議いたしました。\n５、審査の経緯でございます。\n（１）選定の経過は、令和２年８月２１日に社会福祉法人福栄会より、指定管理者指定申請書を受理し、令和２年９月３日に指定管理者候補者選定委員会を開催し、指定管理者候補者を決定いたしました。\n（２）指定管理者候補者選定委員会の構成は、委員長を企画部長として、有識者２名を含め計８名でございました。\n６、選定基準は４項目あり、（１）利用者の平等な利用およびサービスの向上を図るものでること。\n（２）適切な維持および管理を行い、管理に係る経費の縮減を図るものであること。\n（３）管理を安定して行う物的能力、人的能力を有していること。\n（４）設置目的を達成するために十分な能力を有していること。\n７、指定管理者候補者として選定した理由は４項目あり、６の選定基準と選定理由の番号がそれぞれ対応しております。\n（１）母子生活支援施設ひまわり荘の利用者の自立促進に対し、個々の計画に基づく相談・指導や、退所後も関係機関と連携したアフターケアを実施する提案がなされたこと。子育て支援センターの育児支援を目的とした相談事業において、子ども家庭支援センターと連携し、虐待の未然防止・早期発見に取り組むとされていること。\n（２）防災避難訓練の実施や、ヒヤリハット事例の検証、事故発生時の報告、再発防止への取組みおよび緊急時体制の整備などの提案がなされたこと。\n（３）業務遂行の基本的能力となる経営基盤は、公認会計士による事業者経営分析を踏まえて、経営に支障がなく良好であると判断したこと。\n（４）母子家庭に対する自立支援および子育て家庭に対する育児支援を図るものとして、設置目的を理解し達成するための事業計画書（案）が提出されたことでございます。\n８、今後のスケジュールは、指定管理者の指定議案議決後、指定管理者指定決定通知書を送付し、管理運営に関する協議を行い、協定書を締結いたします。"},{"i":280,"speaker":"こんの委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":281,"speaker":"安藤委員","text":"この選定委員会の有識者なのですけれども、２名というのはどのような分野のどのような肩書の方なのか、なぜその方々を選んだのかを伺います。\nそれと子ども家庭支援センター、いわゆる子家センのほうが、今年度から独立して区の直営になったと思うのですけれども、この家庭あんしんセンターの部門を一部持っていたみたいな、その業務のすみ分けはどのような感じで変化があったのか、まとめて伺いたいと思います。"},{"i":282,"speaker":"三ッ橋子育て応援課長","text":"有識者２名でございます。こちらは８月の総務委員会に資料が出されているのですが、今年度、外部委員の導入をいたしております。それが有識者２名となっておりまして、そこでは外部委員は施設の運営に識見を有する者等により選出するとなっておりますので、今回につきましては、子育てや社会福祉に関しての知識があり、品川区のことを理解されている人物を選出し、１人の方は株式会社保育システム研究所代表の吉田正幸委員でして、こちらは品川区の子ども・子育て会議の副会長であるため選出いたしました。そしてもう一人が、日本社会事業大学社会福祉学部准教授の菱沼幹男委員で、こちらは品川区の地域福祉計画の策定委員の委員長であるため選定いたしました。"},{"i":283,"speaker":"崎村子ども家庭支援センター長","text":"子ども家庭支援センターと家庭あんしんセンターの業務のすみ分けという質問でございました。\n今年度、子ども家庭支援センターができまして、これまで前身である子ども育成課児童相談担当と、家庭あんしんセンターとで、虐待の相談ですとか養育困難の家庭相談を受けていたところなのですが、今年度子ども家庭支援センターができまして、そういった虐待、養育困難の相談については、新規の受理から子ども家庭支援センターがすべて引き受けて対応するということにしております。\nこれまで対応していた虐待の対応ですとか養育困難の対応については、これも順次今引継ぎをしておりまして、来年度からはすべて子ども家庭支援センターが担当するといったことで進めているところです。\n家庭あんしんセンターにつきましては、例えばショートステイの事業ですとかトワイライトステイ、また広場事業等を行っておりまして、そういった中から子育てに関する相談、育成相談なども引き続き受けていただいているところでございます。"},{"i":284,"speaker":"安藤委員","text":"分かりました。それと、この指定管理の活用の基本方針に会議録は公表するものとするとあるのですけれども、指定の議案にしては、情報がかなりシンプル過ぎるということがありまして、議事録はつけてもいいのではないかと思うのですけれども、いかがでしょうか。\nそれと、この選定基準についても伺いたいのですけれども、サービスの向上と経費の縮減が並立して書いてあるのですが、福祉の分野においても特に多くの部分は人、人件費だと思いますし、その質を担保するのは専門性を蓄積した人材の継続した確保だと思うのですけれども、ある意味、それと経費の縮減というのは矛盾があると思うのです。これを所管としてはどう両立しようと考えているのかを伺いたいと思いますし、それぞれの選定基準についての点数というのが書かれていないのですけれども、これはなぜなのかというのを併せて伺いたいと思います。"},{"i":285,"speaker":"三ッ橋子育て応援課長","text":"今回、議事録等はつけておりませんでしたけれども、今までもつけてはおりませんでした。実際に議事録の中の質疑応答の内容は、例えばこの場で申し上げますと、離職率に対する質疑、またコロナ禍に対する体制はどのようになっているか、そして第三者評価の結果はどのようになっているか、また経営分析の結果はどのようになっているか、またモニタリング評価の結果はどのようになっているかなどの質疑応答がございました。\nまた、経費縮減についてのご意見もございました。委員がご指摘のように、確かに福祉部門におきましては、やはりサービスの向上と経費の縮減というのは非常に難しいバランスがあるということもご意見としていただいておりました。例えば光熱水費の削減という部分は、削減はしているのですけれども、それは暑くなったときにクーラーをかけないとか、そういう問題ではないと。やはり経費の縮減については、福祉施設としては非常に難しい問題だという提言は実際にございました。\nまた点数について、こちらに書かれてないのはなぜかということでございますけれども、今までも書かれておりませんでしたが、例えば１、２、３、４ございますが、１番については２５点満点、２番についも２５点満点、３番については３０点満点、そして４番については２０点満点、合計１００点満点で審査いたしました。"},{"i":286,"speaker":"安藤委員","text":"大事な議案なので、今まではつけていないということですけれども、やはり所管の判断でぜひ積極的にそこは出していただきたいですし、基本方針に会議録を公表するものとすると書いているのに、一番区民の代表である議会にも出さないとなると、ではどうやってこの会議録を見るのだと思ってしまうので、ぜひ改善をしていただければと思います。点数についてもそうですね。そこら辺は何も隠すものではないと思うので、しっかりと公表していただきたいと思います。要望です。\n最後、選定基準の（３）なのですけれども、管理を安定して行う物的能力および人的能力を有しているというところで、その対応している理由が、経営基盤、公認会計士のみとしか書いていないのですけれども、これはちょっと、それは関わらないとは思いませんけれども、そういう問題なのかなと思っていまして、これだけなのですかというか、人的能力という意味では、やはり福祉施設の管理を安定して行う人的能力というのはただ単に経営基盤だけではないと思いますし、そういった点ではどういう評価をしたのでしょう、評価しなかったのでしょうか。伺いたいと思います。"},{"i":287,"speaker":"三ッ橋子育て応援課長","text":"人的能力につきましては、例えば組織体制のところで家庭あんしんセンターですと、すべてそうですけれども、国の基準よりも定数が、多くの人数で対応しているということが大きいと思われます。また、そのほかそれぞれの方が社会福祉士であるとか、実際に様々な資格や能力を持っているところはございます。"},{"i":288,"speaker":"安藤委員","text":"聞けばいろいろと答えていただけるのですけれども、そういったところはやはり大事な点だと思うので、ここの文面では全くそういうのが見えてこないので、またしっかりと区民に運営実態を明らかにするためにも、そこら辺はきちんと記載を今後充実・工夫していただきたいと重ねて要望させていただきます。"},{"i":289,"speaker":"あべ委員","text":"この事業は継続性が大切だというのは分かるのですが、もう何年もやっているところですので、今回選定理由の中で提案ですとか計画といったところが書いてあるのですけれども、これまでやってきたことの評価はどうなっているのかというのが、この資料からは全く分からないのです。\n例えばアフターケアを実施する提案がなされたこととあるのですけれども、こういうのを読むと、いや、ではこれまでアフターケアはやっていなかったのかという、こうした事業の中でアフターケアまで行うというのは当然のことだと思うのですが、とするとこれだけを読むとやっていなかったのか。もしやっていたのだったらどのような評価でしょうか。\n例えばほかにもあんしんセンターとかは、ヘルパーの派遣とかショートステイ、トワイライトステイとかもやっていますけれども、なかなか使えない。この間は多胎児のお母さんたちにも聞いたのですが、ヘルパー派遣なども使いたかったけれども、結局使えなかったというようなお声も聞いております。これまでの事業の評価というのをどのように見ているのでしょうか。"},{"i":290,"speaker":"三ッ橋子育て応援課長","text":"これまでの事業の評価でございますが、例えばモニタリング評価を実施していること、または第三者評価におきましても高い評価を得られていることが事実としてございます。\nまた、委員の言われましたようにアフターケアの部分でございますが、これまでも退所された方に対しても十分なアフターケアをしておりまして、実際にご相談であったり、また行事に呼ぶなど、切れ目のないように対応しているところでございます。"},{"i":291,"speaker":"あべ委員","text":"第三者評価で高い評価とおっしゃるのですけれども、なかなかこの事業、実績から言っても、これだけ子どもの数が増えていて子育て不安が非常に高まっている、児童虐待の相談件数も増えているという中で、サービスの提供量が少なくともここ数年間全く増えてもいない状況です。本当にニーズに応えていけるのか、それとも自分たちのペースでしかサービスを提供していないのではないかというような疑問を持っているのです。そこはもう十分にニーズに応えているという評価の中で、再度こちらを指定管理者にしようということなのでしょうか。区としては十分だと思っているのでしょうか。"},{"i":292,"speaker":"三ッ橋子育て応援課長","text":"社会情勢に応じて、ニーズは様々変わっていくと思われます。また、そのときそのときのニーズもやはり変わっていくことも考えられますので、今あるニーズに対しては応えていきますし、今後の令和３年からの事業計画の中においても、実際にこのようなニーズに応えていくという提案をなされているところでございます。それらを踏まえて、今回選定させていただきました。"},{"i":293,"speaker":"あべ委員","text":"様々変わるということですが、今、あんしんセンターなり子育て支援に求められていることは上下しているのではなくて、どんどん右肩上がりで増えているというのが通常の認識だと思うのですけれども、それを踏まえてご答弁をいただければと思います。\nそれと今回指定管理者の指定については、この指定管理料というのは出てきていないわけですけれども、これは前回の５年間と金額的には、例えば横ばいなのか下がるのか上がるのか、数字が出せれば数字を出していただければと思うのですが、どのくらいになりそうなのでしょうか。"},{"i":294,"speaker":"三ッ橋子育て応援課長","text":"ニーズにつきましては、確かに委員おっしゃるように右肩上がりだったと思われますので、それに対応していけるように、この指定管理者候補者に対して求めていこうと思っております。\nまた、指定管理料でございますけれども、来年度以降もそれほど変わりはないと捉えております。"},{"i":295,"speaker":"崎村子ども家庭支援センター長","text":"あんしんセンターにおける来年度以降の予算という部分については、先ほどほかの委員からもご質問いただきましたけれども、今年度子ども家庭支援センターができまして、虐待相談・養育困難の相談についての一元化を図ったところでございます。そういった部分で言いますと、相談の業務について一部区の直営化を図ったところでありますので、そういった部分も含めて、来年度以降の予算については検討を進めているところでございます。"},{"i":296,"speaker":"あべ委員","text":"右肩上がりにニーズは増えているという見解が共有できてよかったと思います。決算などを見ておりますとサービス料がほぼ増えておりませんので、今のところはニーズの増加に対応しきれていないのではないかということが、数字の上から導き出されると思います。今後そういったことがないようにしっかりとニーズを拾って、そして対応していただけるように、特にヘルパーなどは本当に使いたいけれども使えなかったというような、ヘルパーがいなくて対応してもらえなかったというような声をいただいておりますので、そうしたこともきちんと法人に伝えて、そういうことがないようにということで、区のほうもしっかりとやっていただければと思います。\nそれから予算のほうなのですけれども、予算を見ていますと年間でこのあんしんセンターは大体５,６００万円ぐらいかと思います。そのうち子育て支援に関わる部分が３,４００万円とかなりの部分を占めているのです。その中で、本年度から区の直営に独立したにもかかわらず、少なくとも今年度については子育て支援センター部分も予算面は全く変わらないままだったと思います。\n以前、委員会の席ではそれは引継ぎのためというご説明をいただきましたが、来年度以降はさすがにそうはならないと思いますので、そこをしっかりと精査して、必要なものは予算をつける、必要でないものについては見直すということをやっていただきたいと思います。\n今後あんしんセンターでは、本年度と来年度以降、次の指定管理では子育て支援センター部分に関わる人数というのは変更があるのでしょうか。"},{"i":297,"speaker":"崎村子ども家庭支援センター長","text":"今委員からお話がありましたように、令和３年度からの基本計画書の案をいただいているところなのですけれども、そこでも子育て支援センターの人員については今年度よりも減ということでいただいておりまして、それを精査させていただいた上で、来年度予算についてはご提案させていただきたいと思っております。"},{"i":298,"speaker":"あべ委員","text":"実績と経験を持った方々がそれをどこかで活かせるような形で、しかしながらその業務に応じた組織にしていただければと思います。\nこちらの選定理由の中で経営基盤が良好とありますけれども、業務が大きく減っても同じ金額である。それは確かに経営基盤が良好になると思うのです。そういうことではなくて、しっかりと運営の面での健全性というのを図っていただければと思います。"},{"i":299,"speaker":"横山委員","text":"７番の部分なのですけれども、アフターケアについてです。退所後も関係機関と連携したアフターケアを実施する提案がなされたこととあるのですけれども、こちらはこれまではどういった機関と連携をしてきたのかを教えてください。\nまた、今回また何か新たに提案があるようでしたら、どのようなアフターケアの提案があったのかというところと、また子ども家庭支援センターとの連携の状況について、まだスタートしたところかと思うのですけれども、やはり連携というところで溝に落ちやすいというところが一般的にありますので、具体的な現状について教えてください。\nまた、事業計画書の案が提出されたということなのですけれども、今後の人材育成についての考え方、何か計画にありますでしょうか。そのあたりも教えてください。"},{"i":300,"speaker":"三ッ橋子育て応援課長","text":"退所後の関係機関につきましては、子育て応援課であったり、子ども家庭支援センターであったり、こちらが関係機関と捉えております。\nまた、アフターケアにつきましても、先ほど申し上げましたように、退所してもこちらのひまわり荘の行事に一緒に参加するなどもしておりまして、実際に途切れないようにしております。"},{"i":301,"speaker":"崎村子ども家庭支援センター長","text":"子ども家庭支援センターとの連携という部分なのですけれども、再三になりますが、今年度虐待の相談とか養育困難の相談を子ども家庭支援センターでお受けするといったことにしておりますけれども、これまで子育て支援センターが相談を受けている中で、育児相談ではなく、やはりかなり不安感の強いもの、またお話を聞く中で虐待してしまっているというような事案を発見したものについてはすぐに子ども家庭支援センターにご連絡をいただいて、我々が対応するといったことはできておりますし、またショートステイ、トワイライトステイの中でもそういった虐待ですとか養育上の不安の強い方というのを引き続き子ども家庭支援センターのほうにつないでいただいて、対応ができるようにしております。委員ご指摘のように、漏れのないように対応してまいりたいと考えております。"},{"i":302,"speaker":"横山委員","text":"アフターケアの新たな提案というのは、今回なかったということなのでしょうか。また、人材育成の部分について、ご答弁をお願いできたらと思います。"},{"i":303,"speaker":"三ッ橋子育て応援課長","text":"アフターケアの新たな部分でございますが、同様と捉えております。\nまた人材育成に関しましては、やはり人事異動などで新人が来る場合などがございますので、そちらに関しましても研修をしっかりとすること、また質の高いサービス提供ができるようにしていくことと捉えております。"},{"i":304,"speaker":"横山委員","text":"これから様々制度ですとかいろいろな動きが出てくるかと思いますので、アフターケアの部分にぜひアンテナを高く持っていただいて、引き続き、今までも母子生活支援施設というのはもちろんアフターケアを行ってきていただいていると私は認識しておりますけれども、そうしたアフターケアを行っていることみたいなところから、虐待の予防ですとか根本解決みたいなところ、そのあたりの新たな施策を打っていく際に、大変貴重な情報源といいますか、そういった現状を分析してその先々の施策に活かしていくというところで注目していただきたいと考えておりますので、ぜひしっかりとそのあたりも連携をしていただきながら、情報共有などもしていただきながら進めていただきたいと考えております。\n人材育成についても、新しい方というのもいらっしゃると思うのですけれども、子ども家庭支援センターですとか、またこちらのひまわり荘ですとか、様々な経験のある方がいらっしゃると思いますので、そうした区が常に持っている経験とか知識などを新しい方にうまく伝達したり、共有したりということもぜひ進めていただきたいと思っていますので、要望で終わらせていただきます。"},{"i":305,"speaker":"あべ委員","text":"トワイライトステイなのですけれども、今年齢の下限の制限があったと思います。ただ、虐待死などは１歳未満が大多数なのですね。そういうことを考えると、今たしか１歳６か月以上でないと預けられなかったかと思うのですけれども、その指定管理が代わるタイミングでも、これをもう少し広げられるようにぜひ法人と話をしてほしいのですが、いかがでしょうか。"},{"i":306,"speaker":"崎村子ども家庭支援センター長","text":"トワイライトステイ、ショートステイなのですけれども、現在利用年齢が１歳６か月以上からといったことでお受けしているところでございます。確かに他区などを見ますと、乳児のショートステイですとかトワイライトステイを実施している区もございます。そういった虐待予防の観点から、ショートステイの拡充については現在も検討しているところなのですけれども、現在乳児院での例えばショートステイなどは、なかなか今のこのコロナの状況でお受けすることが厳しいということで、今回打ち合わせ等々もさせていただいているのですけれども、お話をいただいているところでございます。この家庭あんしんセンターで実施をするのか、それとも乳児院で実施をしていくのかというところについては、今後引き続き検討していきたいと思います。"},{"i":307,"speaker":"こんの委員長","text":"ほかにございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":308,"speaker":"こんの委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、本件につきまして各会派の態度を確認します。\nそれでは、自民党からお願いします。"},{"i":309,"speaker":"芹澤副委員長","text":"賛成します。"},{"i":310,"speaker":"せお委員","text":"賛成です。"},{"i":311,"speaker":"たけうち委員","text":"賛成。"},{"i":312,"speaker":"安藤委員","text":"施設の性格上、運営者に連続性が要求されるという点では異論はありません。また、特に反対する理由もありませんので、賛成です。"},{"i":313,"speaker":"筒井委員","text":"賛成です。"},{"i":314,"speaker":"あべ委員","text":"賛成ではありますけれども、長年同じところに指定管理をさせていることが影響しているのかどうか、やはりより改善をしていく、それから委託費用などのお金の面についてもきっちりと積算が外に出せるような形でしていくということ、もう一度この機会に見直しながらやっていただければと思います。"},{"i":315,"speaker":"横山委員","text":"賛成です。"},{"i":316,"speaker":"こんの委員長","text":"それでは、これより第７５号議案、指定管理者の指定について採決をいたします。\nお諮りいたします。\n本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":317,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(3) 第７６号議案 指定管理者の指定について"},{"i":318,"speaker":"こんの委員長","text":"次に(3)第７６号議案、指定管理者の指定についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":319,"speaker":"吉田保育施設調整担当課長","text":"それでは私から、第７６号議案、品川区立ぷりすくーる西五反田の指定管理者の指定についてご説明いたします。\n１の管理を行わせる施設ですが、本案は西五反田三丁目９番９号に所在いたします品川区立就学前乳児教育施設ぷりすくーる西五反田の指定管理者を変更するものでございます。\n２の指定管理者候補者でございますが、候補者は社会福祉法人福栄会でございます。\n３の指定期間につきましては、現指定管理者からの変更のため、指定期間は現指定管理者の残存指定期間、令和３年４月１日から令和６年３月３１日までの３年間でございます。\n４の候補者の選定でございますけれども、国の認定こども園制度に先駆けて、幼保連携の就学前教育を実施していましたぷりすくーる西五反田につきまして、国の制度に合わせた幼保連携型認定こども園としていくためには運営母体を社会福祉法人化する必要がありまして、現指定管理者である特定非営利法人子育て品川と社会福祉法人福栄会の間で園の運営を移行することで進めてまいりました。また、現指定管理者である特定非営利活動法人子育て品川と社会福祉法人福栄会との間では、業務の引継ぎおよび現在勤務している保育士等の雇用継続について確認した基本合意書が交わされております。保育理念、運営にあたっての知識・技能、幼保連携などの先進的な取組みについて継続するとともに、「品川区指定管理者制度活用に係る指針」に基づき、運営者に連続性が要求されることから、公募によらず特定の事業者を指定管理者候補者として選定を行うこととしまして、選定委員会にその可否について付議を行ったものでございます。\n５の審査の経緯でございます。選定委員会は令和２年９月３日に開催いたしました。指定管理者候補者選定委員会の構成、および裏面になります６の選定基準につきましては表記のとおりでございます。\n７の指定管理者候補者として選定した理由でございますが、候補者として選定するに適切と判断した理由は以下の点でございます。\n（１）ぷりすくーる西五反田の教育および保育に関する全体的な計画に基づき、０歳児から５歳児までの年齢発達の特性を考慮した環境で学びが行えるよう提案がなされていること。\n（２）防災避難訓練の実施やヒヤリハット事例の検証、事故発生時の報告、再発防止への取組みおよび緊急時体制の整備などの提案がなされていること。\n（３）業務遂行の基本的能力となる経営基盤は、公認会計士による事業者経営分析を踏まえて、経営に支障がなく良好であると判断していること。\n（４）保育所および幼稚園の相互の特色を活かした保育および教育を継続的かつ一体的に行うことで、乳幼児の健全な育成を図るとともに、設置目的を理解し達成するための事業計画書（案）が提出されたこと。\n（５）これまで１６年間にわたり培ってきた乳幼児教育における質の高い保育・教育の実績の提供について、引き続き安定的に提供できる提案がなされていることでございます。\n以上の点から、社会福祉法人福栄会を次期指定管理者候補者として選定した次第です。\n８の今後のスケジュールでございますけれども、本委員におけるご審議の結果、ご承認をいただければ、議決を経た後、社会福祉法人福栄会に結果を通知するとともに、来年度以降について展望を持った運営を実現できるように協定の締結を目指してまいります。"},{"i":320,"speaker":"こんの委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":321,"speaker":"安藤委員","text":"こちらについてもかなり簡素な資料なので、ぜひ所管としてはもう少し充実していただきたいということを要望しつつ伺いますけれども、同様に有識者２名はどのような分野のどのような肩書の方なのでしょうか。なぜその方々を選んだのでしょうかというのが１つです。\nそれと理由ですけれども、選定理由の（５）ですが、これまで１６年間にわたり培ってきた保育・教育実績の提供について、引き続き安定的に提供できる提案とありますけれども、具体的にはどのような提案であるのかというのを伺いたいというのが２つ目です。\nそれと、今回基本合意書を結んだとは言っても、指定期間の途中でこれまでの事業者が交代、変更するものなので、指定管理者の新規選定にあたると考えるのが自然だと思うのですけれども、公募でなく特定の事業者の選定にした理由を改めて伺いたいと思います。"},{"i":322,"speaker":"吉田保育施設調整担当課長","text":"３点ご質問をいただいたかと思います。\n有識者２名についてですけれども、子育てや社会福祉に関する知識がありまして、品川区のことを理解されて議論できる方という形で選出したところでございます。１名につきましては、株式会社保育システム研究所の代表の吉田正幸様、この方は子ども・子育て会議の副会長をなさっております。それから、もうお一方が日本社会事業大学社会福祉学部准教授の菱沼幹男様、この方は品川区の地域福祉計画の策定委員会の委員長をなさっている方でございます。\nそれから、ぷりすくーる西五反田の年齢発達の特性を考慮した環境で学びが行える提案の具体的なところでどういうことかと言いますと、事業者からの事業計画書の中で、０歳児から５歳児までの一貫したプログラムの下、保護者、子ども、保育者、地域が向かい合い、乳幼児の健全な育成を主眼とした、預かるから参加する、選択するにシフトした教育と養護を実現というところが、そのほかにもあるのですけれども、分かりやすいところではここの部分だと思います。\nそれから、今回特定の事業者を選定して公募しなかった理由はなぜですかということなのですけれども、今回は平成３１年からの５年間の指定管理の中で、その指定管理を受けたＮＰＯの子育て品川が、認定こども園化を目指すにあたって事業継承を福栄会に行うということで、それで両方の法人が合意をしており、区はそれを確認するということでございます。現在の指定管理者が、ぷりすくーる西五反田の業務をきちんと福栄会に動かせるかどうかというのを確認する意味合いでございます。ＮＰＯ子育て品川の理事会のほうでも、このままではＮＰＯは認定こども園になれないため、発展的なところは今の状態では見込めない。それで、他の社会福祉法人に事業を継承させるということでございます。一緒になることで事業を継承するということです。\nそれで、今の教育水準、それから勤務する人、保育士を含めて雇用の確保がされることを基本合意書のほうで確認していることと、それをはっきりとさせるためにもう一度選定会議を行ったわけです。そのため今回の指定管理期間が３年間というのは、当初決めた残りの残有期間と認識しているところでございます。"},{"i":323,"speaker":"安藤委員","text":"ちょっと理解できないところがあるのですけれども、私が先ほど伺ったのは、選定理由の（１）というよりも（５）のほうを伺ったのです。これは要するに保育士が引き継がれますよという提案のことなのか、この７の（５）はどのような提案がなされたのかというのを伺ったので、それだけ最後に聞かせてください。"},{"i":324,"speaker":"吉田保育施設調整担当課長","text":"これまでのモニタリング評価等で区のほうで評価している部分があるのですけれども、１６年間ここで培ってきたというのは、もともとこのぷりすくーる西五反田自体が、区として国に先駆けて保育と幼稚園を連続させて一体化した仕組みを作ったことです。そちらにつきまして、区としても十分に大事な施設として考えているところと、あとはこの７の（５）というところにはそれを１６年間ずっと続けてこられたというところと、あとはこの仕組みを維持したまま、次の福栄会にその職員、それから運営母体を福栄会のほうでこの内容をそのまま引き続き継続させるという事業提案がございましたので、その内容を判断したところでもございます。"},{"i":325,"speaker":"あべ委員","text":"この件はいろいろな意味でとてもイレギュラーな形で進めていると思っているのですが、先日もちょっと詳しくお話を伺って、大体の流れはそういうことかと思ったのですけれども、ＮＰＯと社会福祉法人とそれから区の思惑が一致したところで、こういうところに行ったのかなと思うのですが、そもそも論として、指定管理者制度というのはその業務に精通した民間のノウハウを取り入れることを目的に設置された制度であると理解しております。とすると、今回福栄会というのは、保育や教育についての実績を持たない法人なのです。とすると、外形的に社会福祉法人ということではありますけれども、保育の施設の指定管理をするにあたって、保育・教育の実績が今のところゼロであるという法人に移行させるということに外形的に躊躇はなかったのか。指定管理でそういうことをしていいのかという思いはなかったのですか。"},{"i":326,"speaker":"吉田保育施設調整担当課長","text":"社会福祉法人の福栄会を紹介するにあたりまして、ＮＰＯ子育て品川のほうからも、ぷりすくーる西五反田におけるこれまで１６年間培ってきた乳幼児教育について、引き続き提供できる社会福祉法人というのを望まれたところでございます。\nその点から、福栄会は保育園は運営していないのですけれども、既にいろいろな意味での幅広い福祉事業を展開しているところと管理運営部門がしっかりとしているということで、まず福栄会を推薦したところと、保育や幼稚園の仕組みについては、今ある母体がそのまま福栄会のほうに入りますので、管理運営は母体として大きくは変わりますけれども、仕組みとしてはそのまま発展的吸収というのか、吸収合併のような形で取り入れられますので、特にその福栄会に替わったことによって質が悪くなるだとか、今までより悪くなるということは想定はしていないところでございます。"},{"i":327,"speaker":"あべ委員","text":"母体がそっくり法人に入るということなので、その母体というのは何ですか。母体というのは通常組織を指す言葉だと思いますけれども、どういう組織がＮＰＯから法人に内包されることになるのでしょうか。ちょっとそこを具体的に教えてください。"},{"i":328,"speaker":"吉田保育施設調整担当課長","text":"ご説明が雑駁で申し訳ございませんでした。組織としましては保育士の部門と、現場における事務部門、それから現場における管理をしている部門、そこの今現在ＮＰＯ子育て品川が運営していた部門がそのまま福栄会のほうに行くという形になります。また、ＮＰＯ側の理事ですけれども、一部の理事等を含めて福栄会のほうに吸収、移行するというような形になります。"},{"i":329,"speaker":"あべ委員","text":"ＮＰＯの理事も福栄会の理事に入るということなのですか。今、そういう答弁があったので、そうすると、逆にそういう条件があればここに移したいと思うＮＰＯの気持ちは分からないでもないですけれども、それはあまりにも心情的なものであって、指定管理者制度とその事業者の変更という意味で、それが妥当なのかどうかというのは、お話を伺っていて余計にちょっと不明瞭になってきました。"},{"i":330,"speaker":"吉田保育施設調整担当課長","text":"誤解を生じさせた答弁で失礼いたしました。ＮＰＯの理事は、福栄会側のほうに移行した際には運営委員会の委員という形になります。ぷりすくーるを運営をするために、ぷりすくーる運営委員会というものを新たに福栄会のほうで立ち上げます。そちらの委員になるというところが、全員ではありませんが、ＮＰＯ側の一部の理事の参加する場所となります。"},{"i":331,"speaker":"あべ委員","text":"今回、そもそもＮＰＯでこうしたぷりすくーるを運営してきたということ自体があまり例のない形であり、それがまた指定管理の期間中に指定管理から外れて別の法人にという、これもまたイレギュラーでなかなか似たようなことが今後起こるかどうか、なかなか起こらないとは思うのですけれども、１つには、その分野の実績がない事業者に対して指定管理を新たに行うということ、これを前例にしてほしくないというのが一つあります。\nその次の事業者を選ぶにあたって、従前の事業者が次の事業者を事実上選び、その運営の中に入っていくという、これも前例にしてほしくないやり方なのです。これができてしまうと、一旦指定管理を受けた事業者というのは、自らの選定によって途中で事業者の変更が事実上できるということになってしまうので、指定管理者制度のやり方としてはかなり逸脱したものであると私は考えております。\nですので、今回非常にイレギュラー掛けるイレギュラーみたいな形ですので、顔見知りの中でこういう話がまとまったという流れなのでしょうけれども、指定管理のそもそものやり方としてはぜひほかではやってほしくないやり方です。これはぜひ強調しておきたいと思います。これについては、部長からもご答弁いただけると大変ありがたいです。\nもう一つは内容面です。福栄会は障害児施設なども運営している法人ですので、ここの選定理由に全く出てきていないのですけれども、こうして幼児教育・保育を行うのであれば、そうした面を逆に活かしていくということもぜひアピールをして実施していただきたいところなのですが、そこについて全く触れられていないのは大変残念なのです。そうした話は出ているのでしょうか。"},{"i":332,"speaker":"柏原子ども未来部長","text":"指定管理の大きな部分のところもございますので、私のほうからお話しさせていただきますと、これまでも当委員会でご報告を幾つかさせていただいた中で、このぷりすくーる西五反田の経緯をお話しさせていただいたところです。委員におっしゃっていただいたとおり、確かにイレギュラーです。ちょっとこういう指定の仕方というのは、恐らく過去もありませんし、これからも恐らくこういうちょっと時間的なずれみたいなところも含めて、ないだろうと言い切れるものではないのですけれども、ないものだとは思っています。\n今回のこの指定管理の部分については、こちらの選定理由のところにもありましたけれども、１６年間ずっと品川区が先駆的にやってきたこの教育と乳幼児の保育とを一体化したものというのは、品川区から発信しているような部分もあった事業ではあったのですが、逆に国のほうのこの制度が大きく動いた中で、その枠に入り切れない事業になってしまったということがありました。それができるのが、認定こども園という形にするということなのですが、ＮＰＯがそれになれないということでしたので、社会福祉法人化というのをずっと探っていたところなのですが、それもままならないというのがありまして、その間に前回の指定期間が切れてしまうという事態になったと。\nその後についてはこの事業をやっていきたいという区の思いもあったので、今のＮＰＯに指定をしたのですが、社会福祉法人化というところにはまだ課題が残っていましたので、それをずっと検討していたというところがあります。そういった中で、この福栄会という社会福祉法人は、一定程度社会福祉法人としての実績もあるところにということで、紹介という形というご答弁はしましたけれども、話をしてもらっていたというところです。\n今回その福栄会のほうも、この乳幼児教育をやるという思いが、福栄会の中でも児童部門というのを新たにもう一回立ち上げ直すとか、そういう再編をして、そういった流れで出てきているというのがありましたので、課長が先ほど来答弁していますとおり、今のぷりすくーる西五反田でやっている保育士とかいろいろなスタッフ、そういった方々がそのまま入るというのを大きな条件としてやりたいというお話もあったというところから、引き継ぎのような見え方になっていますけれども、こういう動きになったところがあります。\nですので、指定管理の期間についても残存の３年間ということであえて指定をさせていただいて、事業者が替わるということですから、公募をして５年間という考え方もあるのですが、まずは区としては今までやってきたこの乳幼児教育のここの最先端の部分をさらに大きく発展させ、継承するというところが区として事業の一番の目的としてありましたので、まずこの３年間を指定するという形になったということです。\nその先については、この社会福祉法人化に当たっていろいろと課題もまだありますので、それを今後解決していってもらわなくてはいけないというところはありますけれども、その先はその先でもう一回新たにまた判断しなくてはいけないというところがありますので、ちょっといろいろとしゃべってしまいましたが、ひとまずこの判断をさせていただいた中で、今回はそういったイレギュラーの中での区としての判断を入れさせていただいたというところでございます。\nそれから、後段のご質問の部分です。そういった前提としてあったこの事業をまず継続させるのだというところがありますので、福栄会のほうも今あるぷりすくーる西五反田のこの事業というのをきちんとやっていくのだという提案のされ方ということでしたので、新たに何か活かして何かやっていきたいというお言葉をいただいていましたけれども、具体的な提案としてはここには出てきていませんが、それは今後の展開の中でということになろうかと思います。"},{"i":333,"speaker":"こんの委員長","text":"ほかにございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":334,"speaker":"こんの委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、本件につきまして各会派の態度を確認します。\nそれでは、自民党からお願いします。"},{"i":335,"speaker":"芹澤副委員長","text":"賛成します。"},{"i":336,"speaker":"せお委員","text":"賛成です。"},{"i":337,"speaker":"たけうち委員","text":"賛成です。"},{"i":338,"speaker":"安藤委員","text":"賛成です。施設の性格上、また通っている子ども、利用者にとっても運営者の連続性が要求されている点では異論はないので、賛成です。"},{"i":339,"speaker":"筒井委員","text":"賛成です。"},{"i":340,"speaker":"あべ委員","text":"いろいろと課題があると思いますが、賛成はいたします。ただ、この指定管理の持つ制度的な危うさというのをぜひ前例にはしないでいただきたいと思います。"},{"i":341,"speaker":"横山委員","text":"賛成です。"},{"i":342,"speaker":"こんの委員長","text":"それでは、これより第７６号議案、指定管理者の指定について採決をいたします。\nお諮りいたします。\n本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":343,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は全会一致で原案のとおり可決決定いたしました。\n以上で、本件および議案審査を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(1) 令和２年請願第１４号 品川区私立幼稚園保護者負担教育費の軽減に関する請願"},{"i":344,"speaker":"こんの委員長","text":"次に、予定表２の請願・陳情審査に戻りまして、(1)令和２年請願第１４号、品川区私立幼稚園保護者負担教育費の軽減に関する請願を議題に供します。\n本件は初めての審査でありますので、書記に朗読をさせます。\n〔書記朗読〕"},{"i":345,"speaker":"こんの委員長","text":"朗読が終わりました。\nそれでは本件に関しまして、理事者よりご説明願います。"},{"i":346,"speaker":"若生保育支援課長","text":"私から、本請願についてご説明させていただきます。\nまず、入園料補助金に関してですが、こちらは過去数回の増額を経まして、現在１０万円を私立幼稚園に入園した保護者へ補助しているところです。\n次に、私立幼稚園の振興のための直接助成金につきましては、昨年１０月にスタートした幼児教育・保育の無償化に伴う園の事務負担等を考慮し、今年度より運営費補助を１園当たり１００万円増額し、２２０万円としたところでございます。\nまた運営費のほか、教材費、研修費、健康管理増進費、心身障害児教育事業費、防災安全対策費、インフルエンザ予防接種費、衛生管理費についてそれぞれ補助を行っているところです。\n次に、保護者教職員連合会への助成ですが、私立幼稚園協会に対し５５０万円の補助をしており、そのうち保護者教職員連合会が実施する研修や講演会等において会場費や講演料などに充てられています。\nこれまでも適宜助成額の増額やメニュー拡充に努めてまいりましたが、今後も私立幼稚園を取り巻く状況の変化を見極めつつ、保護者負担の軽減と幼児教育の充実を図るため、必要な支援を行ってまいります。"},{"i":347,"speaker":"こんの委員長","text":"説明が終わりました。\nそれでは、本請願につきまして、ご質疑、ご意見等がございましたらご発言願います。"},{"i":348,"speaker":"たけうち委員","text":"そうすると、この入園料１０万円補助ということで、実際に所得によって若干お支払いされている差額が違ってくるとは思うのですけれども、大体平均して入園料にどのぐらいの負担が出ているのか。それから、今ここにはもう書いていないので、ほとんど負担がなくなってきたのかと思うのですけれども、幼児教育・保育の無償化ということなので、この保育料についての負担というのは、もうほぼないと思っていいのかどうか。その２点をお願いします。"},{"i":349,"speaker":"若生保育支援課長","text":"まず入園料のお尋ねですけれども、こちらは所得に関係なく定額になってございまして、区内の私立幼稚園１８園で平均が１３.５万円ほどでございますので、平均から、１０万円ということですので３万円ちょっとはご負担いただくという形になっております。\nそれから、無償化に伴いまして保育料の負担のほうがどうなっているかというところでございます。こちらは、国のほうでの無償化の給付に関しましては、これは完全な無償化というわけではなく、制度上は一律２万５,７００円を上限とした給付になってございます。ただ、品川区におきましてはこれまでも就園奨励費という形で補助していた部分がございますので、そういったところを今回上乗せの部分として、園児保護者補助金という仕組みは残した上で負担軽減を図っているというところで、保育料等はそれぞれの園によって異なるので、所得階層ですとか、お子様の第１子、第２子というところでも異なってくるところではございますけれども、現在調べますと、完全に無償になっている割合は、半数程度の方が完全に補助金で賄われるような状況で、それ以外でも若干の負担はいただくのですけれども、約２割ぐらいの方が１,０００円未満の負担で済んでいるというということで、全体で言うと７割ぐらいがほぼ負担がないという状況になっているところでございます。"},{"i":350,"speaker":"たけうち委員","text":"詳しくありがとうございます。本当にそういった面では、保育料のほうも国においての無償化がされて、ほぼ７割が負担なしということで大変よくなって、また品川区もこの間、こちらにも紹介していただいているとおり、本当に数年単位で拡充を図ってこられていることに大変敬意を表するところでございます。\nただそうは言っても、今あったとおり入園料の補助金等においてはまだ若干の公私格差があるということでのこういった内容になっておりますので、ぜひとも区としてもまた検討いただいて、この請願のとおり拡充してもらえればと思いますが、一応そのことについてのコメントだけいただけますか。"},{"i":351,"speaker":"若生保育支援課長","text":"これまでも様々な補助メニューを拡大してまいりましたけれども、今般の私立保育園等の補助金を拡充しているところもございまして、そことの負担のバランスというところも考慮しつつ、今後の私立幼稚園のほうの教育の振興に資するために、様々な支援を検討してまいりたいと考えております。"},{"i":352,"speaker":"あべ委員","text":"昨年の幼児教育の無償化以降、全国では保育料の値上げをした園がかなり目立つわけですけれども、品川区内では把握をされていますでしょうか。"},{"i":353,"speaker":"若生保育支援課長","text":"昨年度、無償化に伴っていろいろと便乗値上げみたいなところで報道がなされて、そういったことはちょっと控えるようにということで通知等も国のほうから出ていたところで、昨年度については保育料を値上げしたというところは聞いてございません。\nただ、今年度に入ってからは、やはりこういった社会情勢等の中で若干値上げが、教育の充実をしたいですとか、職員の処遇をもう少し上げていきたいというような各園のご事情も踏まえて、数園が値上げをしたというところはございます。"},{"i":354,"speaker":"あべ委員","text":"無償化の影響もあって、保護者負担は以前に比べればかなり軽減されてきたかなと思います。さらなる軽減というのももちろん理解をするところですが、今おっしゃったみたいに職員の処遇改善ですとか、あるいは特別支援にかけるサービスの充実ですとか、そうした形でのお金の使い方というのもバランスを持って進めていただければと思います。"},{"i":355,"speaker":"安藤委員","text":"私立幼稚園保護者教職員連合会の活動について、区はどのように把握しているのかを伺いたいと思います。保護者と教職員との連携・交流というのは、よりよい幼稚園環境を作る上でも大切なことだと思いますけれども、いかがでしょうか。"},{"i":356,"speaker":"若生保育支援課長","text":"保護者教職員連合会の活動でございますけれども、こちらにつきましては、令和元年度の実績報告が協会から上がってくるのを見ますと、母親研修ですとか、保護者教職員連合大会、これは講演会ですね、そういったところに補助金が使われていると聞いておりますので、そういった活動や、保護者・教職員相互の連携を図ったりしながら、家庭教育も含めて幼児教育に貢献しているということで、各園の教育と相まってそういった教育の下支えをしているということで、区としても認識しております。"},{"i":357,"speaker":"安藤委員","text":"やはり子どもに向き合っている園の職員と保護者との交流というのは一定大切かなと思っていまして、区立保育園についてはどのように行われているのかを改めて伺いたいと思います。\nまた、これもちょっと大事なので区立保育園のほうでちょっと聞かせてください。今やはり重要だという話もあったので、やはりかつて区立の保育園ではこういう活動というのは、保育の質を保つ上で大切な役割を果たしていたと伺っていますけれども、幼稚園では行われているようなことが、区立の保育園では大分弱くなっているというか、むしろそれをあまりさせないような方向になっているように私は感じていまして、昨今、私も２年前までは区立園に子どもが通っていたのですけれども、やはり非常に弱くなっているなと感じています。若干ずれてしまうかもしれませんけれども、区立の保育園や幼稚園についても、保護者と従事者との交流はもっと自由に活発に行えるようにしたほうが子どものためにもよいと思うのですが、いかがでしょうか。"},{"i":358,"speaker":"こんの委員長","text":"安藤委員、請願の内容はご承知のとおり私立幼稚園で、参考までにお聞きしたい気持ちはよく分かるのですが、この件については私立幼稚園と、請願の中身に沿ってのことだけお答えをいただくということで判断させていただきたいと思いますので、よろしくお願いします。なので、私立幼稚園に関することのみということにさせていただきます。"},{"i":359,"speaker":"安藤委員","text":"区立幼稚園に関しては現状はどうですか。"},{"i":360,"speaker":"こんの委員長","text":"参考までに、区立幼稚園。"},{"i":361,"speaker":"立木保育課長","text":"区立幼稚園のほうにもＰＴＡはございますので、同じような活動をしていると認識しております。"},{"i":362,"speaker":"横山委員","text":"現在の私立幼稚園を取り巻く社会情勢、そういった現場の状況というあたりを、区としては具体的にどのように把握をしておりますでしょうか、確認させてください。"},{"i":363,"speaker":"若生保育支援課長","text":"私立幼稚園の現場を取り巻く状況の把握につきましては、私立幼稚園は私立保育園等々と違って、各園が建学の精神に基づいて運営しておりまして、区が補助をしているとはいえ、日々ちょっとそういう活動のお話を伺う機会はなかなかないところではあるのですが、私立幼稚園協会の会長とはかなり頻繁にやり取りをさせていただいて、その中から課題ですとか状況をお伺いする機会はよくあるところでございます。\nまた、幼稚園担当の職員は、書類のやり取りの中から各園のお話、ご要望を聞く機会もございますので、そういったところで状況等の把握に努めているところでございます。"},{"i":364,"speaker":"横山委員","text":"品川区だけに限らず全国的な傾向なのですけれども、私は私立幼稚園が教育の質で選ばれるような時代に向かっているのではないかと捉えているところです。また保護者の方々の要望というのも、様々個別であったり高い要望もあるような現状があると捉えております。\nまた他の自治体の事例なのですけれども、特徴のある取組みに果敢にチャレンジをしていくということはすごく大事だと思うのですが、そうして成果を上げようとすると、子どもにとって厳しい指導になってしまうような場合もあるなど、チャレンジをしたくてもなかなか課題があるとも聞いているところです。\nそうした現場の疲弊ですとか大変さ、つらさ、さらにコロナ禍という中で、保護者の方の様々な思いですとか、また現場の先生方の思いがあるのではないかと思っておりますけれども、現在も既にいろいろとお話を聞く機会なども捉えていただいたり、書類の面でやり取りしていただいたりしていると思っているのですが、現場の皆様がどのようなことにお困りであるのかということを丁寧に聞いて、引き続き誠実な対応をお願いしたいと思いますので、こちらは強く要望させていただきたいと思います。こちらは区のご見解をお聞かせいただけたらと思っています。\nまた、そうした現場の大変さというところですけれども、区が分かっていて理解はしていて共有していただいているということなのですが、それを分かってもらっているのだということを、現場にも、保護者の方、先生方、いろいろな方々を含めてしっかりと実感をしていただくということもすごく大事だと思っておりまして、みんなで手を組んでチームとして子どもたちを育んでいくというような気運の醸成を区がリードして、そういった雰囲気づくりということも大切にしていただきたいと思っておりますので、ご意見をお聞かせいただけたらと思います。"},{"i":365,"speaker":"若生保育支援課長","text":"私立幼稚園の保護者の皆様とか教員の皆様の思いというところ、これはやはりこれまで区としてもなかなか聞き取るのに十分な体制にはなっていない部分も確かにあると認識しております。今後、昨年度から幼児教育・保育の無償化によりかなり制度も変わって、私立幼稚園との関わりというところも、区としても今検討しなくてはならない段階に来ているかなというところは非常に認識しているところでございます。\n今後のそういった私立幼稚園とどのように関わっていってよい教育をしていただくかというところ、ニーズ等をどうくみ上げていくかというところは、ご意見を伺いながら検討してまいりたいと考えています。"},{"i":366,"speaker":"横山委員","text":"ぜひ引き続き連携を取りながらよろしくお願いいたします。"},{"i":367,"speaker":"こんの委員長","text":"ほかにございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":368,"speaker":"こんの委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\nそれでは、まず、令和２年請願第１４号の取扱いについてご意見を伺いたいと思います。継続にする、あるいは結論を出す、とちらかご発言願います。また結論を出すのであれば、その結論についてもご発言ください。\nそれでは、自民党からお願いします。"},{"i":369,"speaker":"芹澤副委員長","text":"本日結論を出すで、採択でお願いします。"},{"i":370,"speaker":"せお委員","text":"本日結論を出すで、採択でお願いします。\n在宅子育ての方とかも地域に関わったりとか、同じ年代の子どもたちと関わることは大切ですので、私立幼稚園の役割はすごく大きいと思っています。あと、私立幼稚園しか選択肢がない方もいらっしゃいますので、そういった方にも重要かと思っています。\nただ、私は先日の決算特別委員会でもちょっと発言させていただいたのですけれども、途中で退園を促すなどの不適切な対応がないかというのを、私立だから区から口を出せないとかそういうことではなく、補助金を出していますので、区で調査、把握していただいて、指導などはしていってほしいと要望させていただきます。"},{"i":371,"speaker":"たけうち委員","text":"本日結論を出す、採択でお願いします。\n理由は先ほど質疑の中で述べたとおりです。"},{"i":372,"speaker":"安藤委員","text":"本日結論を出すで、採択です。\n幼児教育の無償化につながる内容なので、賛成です。"},{"i":373,"speaker":"筒井委員","text":"本日結論を出すで、採択でお願いします。\n公私の教育費格差の解消に向けて進めていっていただきたいと考えております。"},{"i":374,"speaker":"あべ委員","text":"本日結論を出すで、採択でお願いします。\n子育てに関する広範な費用の軽減を進めていただきたいと思います。この件も、そしてその他のことについても区として指導していただければと思います。"},{"i":375,"speaker":"横山委員","text":"結論を出すで、採択でお願いします。"},{"i":376,"speaker":"こんの委員長","text":"それでは、令和２年請願第１４号につきまして、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":377,"speaker":"こんの委員長","text":"それでは、令和２年請願第１４号は、結論を出すことに決定いたしました。\n先ほどの質疑でそれぞれの方のご意見を伺いましたので、令和２年請願第１４号につきましては、簡易採決により採決を行います。\nお諮りいたします。\n令和２年請願第１４号、品川区私立幼稚園保護者負担教育費の軽減に関する請願を、採択することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":378,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって本件は採択と決定いたしました。\n以上で、請願・陳情審査を終了いたします。\n────────────────────────────────────────────\n３ その他\n(2) 委員長報告について"},{"i":379,"speaker":"こんの委員長","text":"最後に、予定表３のその他に戻りまして、(2)委員長報告についてを議題に供します。\n本日の議案審査の委員長報告については、正副委員長にご一任いただきたいと思いますがよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":380,"speaker":"こんの委員長","text":"ありがとうございます。それでは正副でまとめさせていただきます。\n────────────────────────────────────────────\n(3) その他"},{"i":381,"speaker":"こんの委員長","text":"次に、(3)その他を議題に供します。\nその他で何かございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":382,"speaker":"こんの委員長","text":"ないようですので、以上でその他を終了いたします。\n以上で本日の予定はすべて終了いたしました。\n明日も午前１０時からの開会となりますので、よろしくお願いいたします。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ５時１９分閉会"}]});
